-- ============================================================
-- 033_ielts_speaking_lessons.sql
-- 39 lessons transcribed from "IELTS Speaking Band 5 to 8": 20 under
-- a new Foundations topic (general skills -- fluency, vocabulary,
-- grammar, pronunciation, mistakes, practice methods) and the rest
-- split across the existing Part 1/2/3 topics (a masterclass lesson,
-- topic-grouped Band 8 model answers, and a practice-question
-- appendix, per part). Model answers get an inline "Listen to this
-- answer" pronunciation button (Web Speech API) so students can hear
-- a full Band 8 answer spoken aloud, not just single words.
-- ============================================================

do $$
declare
  v_foundations uuid;
  v_part_1 uuid;
  v_part_2 uuid;
  v_part_3 uuid;
begin
  select cn.id into v_foundations from content_nodes cn
    join content_nodes speaking on cn.parent_id = speaking.id
    join content_nodes ielts on speaking.parent_id = ielts.id
    where ielts.slug = 'ielts' and speaking.slug = 'speaking' and cn.slug = 'foundations';

  select cn.id into v_part_1 from content_nodes cn
    join content_nodes speaking on cn.parent_id = speaking.id
    join content_nodes ielts on speaking.parent_id = ielts.id
    where ielts.slug = 'ielts' and speaking.slug = 'speaking' and cn.slug = 'part-1';

  select cn.id into v_part_2 from content_nodes cn
    join content_nodes speaking on cn.parent_id = speaking.id
    join content_nodes ielts on speaking.parent_id = ielts.id
    where ielts.slug = 'ielts' and speaking.slug = 'speaking' and cn.slug = 'part-2';

  select cn.id into v_part_3 from content_nodes cn
    join content_nodes speaking on cn.parent_id = speaking.id
    join content_nodes ielts on speaking.parent_id = ielts.id
    where ielts.slug = 'ielts' and speaking.slug = 'speaking' and cn.slug = 'part-3';

  -- How the Speaking Test Works
  insert into lessons (node_id, title, slug, excerpt, content, status, difficulty, estimated_minutes, published_at)
  values (v_foundations, 'How the Speaking Test Works', 'how-the-test-works', 'Test structure, what the examiner does (and doesn''t do), and how to use this book.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"ভূমিকা — Speaking-এ ৬ থেকে উঠতে না পারার আসল কারণ"}]},{"type":"paragraph","content":[{"type":"text","text":"২০ বছরে হাজার হাজার mock interview নিয়েছি। একটা জিনিস বারবার দেখেছি: যে শিক্ষার্থী Reading-এ ৮ পায়, সে Speaking-এ ৫.৫ পেতে পারে। ইংরেজি জানা আর ইংরেজিতে কথা বলতে পারা — দুটো আলাদা দক্ষতা।"}]},{"type":"paragraph","content":[{"type":"text","text":"কিন্তু আসল সমস্যাটা আরও গভীরে। বেশিরভাগ শিক্ষার্থী Speaking পরীক্ষাকে ইংরেজির পরীক্ষা ভাবে। এটা ইংরেজির পরীক্ষা নয় — এটা কথোপকথনের পরীক্ষা, যা ইংরেজিতে হয়। পার্থক্যটা বিশাল। Examiner দেখছেন না তুমি কত শুদ্ধ ইংরেজি জানো; দেখছেন তুমি স্বাভাবিকভাবে ভাব প্রকাশ করতে পারো কিনা।"}]},{"type":"paragraph","content":[{"type":"text","text":"বাংলাদেশি শিক্ষার্থীদের নম্বর হারানোর পাঁচটি কারণ, ঠিক এই ক্রমে:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ছোট উত্তর। \"Do you like music?\" → \"Yes, I like music very much.\" শেষ। Examiner তোমাকে মাপার মতো ভাষাই পান না। কম কথা = কম নম্বর, সবসময়।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"মুখস্থ উত্তর। কোচিং থেকে শেখা তৈরি উত্তর examiner সাথে সাথে ধরে ফেলেন — কণ্ঠস্বর বদলে যায়, চোখ উপরে চলে যায়। ধরা পড়লে সেই অংশ নম্বর গণনার বাইরে চলে যায়।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"নীরবতা ও \"মানে... আসলে...\" — চিন্তা করার সময় বাংলা ফিলার বেরিয়ে আসে বা পুরোপুরি থেমে যায়। এটি সরাসরি Fluency-তে আঘাত।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"একঘেয়ে ভাষা। \"very good\", \"very important\", \"I think\", \"I think\", \"I think\" — Lexical Resource ৫-৬-এ আটকে যায়।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"উচ্চারণ নয়, বোধগম্যতা। Examiner তোমার বাঙালি accent-এ নম্বর কাটেন না — কিন্তু \"very\" যদি \"wery\" শোনায় আর \"sitting\" যদি \"shitting\" শোনায়, তখন কাটে।"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"এই পাঁচটার প্রতিটির নির্দিষ্ট, শেখানো যায় এমন সমাধান আছে — এবং সেগুলোই এই বইয়ের বিষয়।"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"একটা প্রতিশ্রুতি Speaking হলো IELTS-এর একমাত্র মডিউল যেখানে ৩০ দিনে ১.৫ ব্যান্ড লাফ দেওয়া বাস্তবসম্মত — কারণ বেশিরভাগ শিক্ষার্থীর ইংরেজি জ্ঞান ইতিমধ্যেই ৭ ব্যান্ডের, শুধু প্রকাশ করার পদ্ধতি ৫ ব্যান্ডের। এই বইয়ের ২১টি অধ্যায় শেষ করে যদি প্রতিদিন ১৫ মিনিট নিজের কণ্ঠ রেকর্ড করে শোনো, তোমার Speaking প্রায় নিশ্চিতভাবে ৬.৫–৭.৫ রেঞ্জে পৌঁছাবে।"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"এই বইটি কীভাবে ব্যবহার করবে"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"সবচেয়ে গুরুত্বপূর্ণ নিয়ম — পড়া নয়, বলা"}]},{"type":"paragraph","content":[{"type":"text","text":"এই বইটা চুপচাপ পড়লে কোনো কাজ হবে না। Speaking-এ উন্নতি হয় মুখের পেশি, কান আর মস্তিষ্কের অভ্যাস বদলে — চোখ দিয়ে নয়।"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"প্রতিটি model answer জোরে পড়ো, অন্তত একবার।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"প্রতিটি অনুশীলন প্রশ্নের উত্তর রেকর্ড করো (ফোনের voice recorder যথেষ্ট)।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"নিজের রেকর্ডিং শোনো। এটাই সবচেয়ে অস্বস্তিকর কাজ, এবং সবচেয়ে কার্যকর। প্রথম তিন দিন খারাপ লাগবে; চতুর্থ দিন থেকে নিজের ভুল নিজেই ধরতে শুরু করবে।"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"দুটি পথ"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"পথ"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"কাদের জন্য"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"ক্রম"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"পূর্ণ প্রস্তুতি (৩০ দিন)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"পরীক্ষা এক মাস বা তার বেশি দূরে"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ১ → ২১ ক্রমানুসারে + শেষের ৩০ দিনের প্ল্যান"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"জরুরি (১০ দিন)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"পরীক্ষা খুব কাছে"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ২ → ৪ → ৫ → ৭ → ১২ → ১৪ → ১৬ → ১৭ → ১৮ → ২০"}]}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"যা করবে না ❌ Model answer মুখস্থ করবে না। Examiner প্রশিক্ষিত — মুখস্থ ভাষা চিনতে তাঁর ১০ সেকেন্ড লাগে। ধরা পড়লে ওই অংশ মূল্যায়নের বাইরে চলে যায়, অর্থাৎ তুমি কার্যত কিছুই বলোনি। ❌ কঠিন শব্দের তালিকা মুখস্থ করে গুঁজে দেবে না। কথা বলার সময় ভুল জায়গায় বসানো একটা \"plethora\" তোমার Lexical Resource কমায়। ❌ Accent নকল করার চেষ্টা করবে না। ব্রিটিশ বা আমেরিকান accent-এ কোনো বাড়তি নম্বর নেই। বোধগম্যতাই একমাত্র মাপকাঠি।"}]}]},{"type":"paragraph","content":[{"type":"text","text":"সূচিপত্র  |  Contents"}]},{"type":"paragraph","content":[{"type":"text","text":"ভূমিকা — Speaking-এ আটকে থাকার আসল কারণ"}]},{"type":"paragraph","content":[{"type":"text","text":"এই বইটি কীভাবে ব্যবহার করবে"}]},{"type":"paragraph","content":[{"type":"text","text":"PART 1 — ভিত্তি"}]},{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ১ — Speaking Test: পরীক্ষার আসল চিত্র"}]},{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ২ — চারটি Marking Criteria"}]},{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ৩ — Band 5, 6, 7, 8: আসল পার্থক্য"}]},{"type":"paragraph","content":[{"type":"text","text":"PART 2 — Fluency & Coherence"}]},{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ৪ — Fluency আসলে কী (এবং কী নয়)"}]},{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ৫ — উত্তর লম্বা করার তিনটি ইঞ্জিন"}]},{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ৬ — Coherence: কথ্য ইংরেজির সংযোগ"}]},{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ৭ — থেমে গেলে কী করবে: Recovery Toolkit"}]},{"type":"paragraph","content":[{"type":"text","text":"PART 3 — Lexical Resource"}]},{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ৮ — Speaking-এ শব্দভাণ্ডার: নিয়ম আলাদা"}]},{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ৯ — Idiomatic Language: Band 7-এর চাবি"}]},{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ১০ — টপিক ভোকাবুলারি: যা সত্যিই কাজে লাগে"}]},{"type":"paragraph","content":[{"type":"text","text":"PART 4 — Grammar"}]},{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ১১ — Speaking-এর ১০টি বাক্যগঠন"}]},{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ১২ — বাংলাদেশি শিক্ষার্থীদের ৩০টি Speaking Mistake"}]},{"type":"paragraph","content":[{"type":"text","text":"PART 5 — Pronunciation"}]},{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ১৩ — Pronunciation-এ আসলে কী মাপা হয়"}]},{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ১৪ — বাংলা-ভাষীদের নির্দিষ্ট উচ্চারণ সমস্যা"}]},{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ১৫ — উচ্চারণ অনুশীলনের পদ্ধতি"}]},{"type":"paragraph","content":[{"type":"text","text":"PART 6 — Masterclass (Model Answers)"}]},{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ১৬ — Part 1 Masterclass"}]},{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ১৭ — Part 2 (Cue Card) Masterclass"}]},{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ১৮ — Part 3 Masterclass"}]},{"type":"paragraph","content":[{"type":"text","text":"PART 7 — কৌশল ও অনুশীলন"}]},{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ১৯ — পরীক্ষার দিনের কৌশল"}]},{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ২০ — সঙ্গী ছাড়া একা অনুশীলনের পদ্ধতি"}]},{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ২১ — নিজের মূল্যায়ন ও Error Log"}]},{"type":"paragraph","content":[{"type":"text","text":"APPENDIX"}]},{"type":"paragraph","content":[{"type":"text","text":"A — Part 1: ১০০টি প্রশ্ন"}]},{"type":"paragraph","content":[{"type":"text","text":"B — Part 2: ৪০টি Cue Card"}]},{"type":"paragraph","content":[{"type":"text","text":"C — Part 3: ৬০টি Discussion Question"}]},{"type":"paragraph","content":[{"type":"text","text":"D — Functional Language Bank"}]},{"type":"paragraph","content":[{"type":"text","text":"E — ৩০ দিনের Speaking Plan"}]},{"type":"paragraph","content":[{"type":"text","text":"শেষ কথা"}]},{"type":"paragraph","content":[{"type":"text","text":"পৃষ্ঠা নম্বরসহ সূচিপত্র"}]},{"type":"paragraph","content":[{"type":"text","text":"Word-এ খোলার পর টেবিলের উপর ডান-ক্লিক করে \"Update Field\" চাপলে পৃষ্ঠা নম্বরসহ সূচিপত্র তৈরি হবে।"}]},{"type":"paragraph","content":[{"type":"text","text":"ভিত্তি"}]},{"type":"paragraph","content":[{"type":"text","text":"পরীক্ষার ঘরে আসলে কী হয়, এবং examiner কী মাপছেন"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অধ্যায় ১ — Speaking Test: পরীক্ষার আসল চিত্র"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"১.১ কাঠামো"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"অংশ"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"সময়"}]}]},{"type":"tableHeader","content":[