"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"✅ তিনি যা করেন"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"❌ তিনি যা করেন না"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"চারটি criteria ধরে নম্বর দেন"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"তোমার মতামতের সাথে একমত কিনা বিচার করেন না"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"তুমি কতটা স্বাভাবিকভাবে বলছ তা লক্ষ করেন"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"তোমার তথ্য সত্যি কিনা যাচাই করেন না — গল্প বানানো সম্পূর্ণ বৈধ"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"প্রয়োজনে থামিয়ে পরের প্রশ্নে যান (সময়ের কারণে, বিরক্তির কারণে নয়)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"তোমার accent-এ নম্বর কাটেন না"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"নিরপেক্ষ মুখভঙ্গি রাখেন"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"হাসছেন না বা মাথা নাড়ছেন না মানে খারাপ হচ্ছে — এমন নয়"}]}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"সবচেয়ে মুক্তিদায়ক সত্য তোমার উত্তর সত্যি হতে হবে না। \"Describe a book you recently read\" — তুমি বই না পড়লেও বানিয়ে বলতে পারো। Examiner সত্যতা মাপছেন না, ভাষা মাপছেন। যে গল্পে তুমি সবচেয়ে সাবলীলভাবে কথা বলতে পারবে, সেটাই বলো।"}]}]}]}'::jsonb, 'published', 'advanced', 10, now());

