  insert into lessons (node_id, title, slug, excerpt, content, status, difficulty, estimated_minutes, published_at)
  values (v_foundations, 'The Four Marking Criteria', 'the-four-marking-criteria', 'Fluency & Coherence, Lexical Resource, Grammatical Range & Accuracy, and Pronunciation -- what each one actually measures.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অধ্যায় ২ — চারটি Marking Criteria"}]},{"type":"paragraph","content":[{"type":"text","text":"চারটি criteria, প্রতিটি ২৫%। এগুলো না বুঝে অনুশীলন করা মানে অন্ধকারে ঢিল ছোড়া।"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Criterion"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"সংক্ষেপে"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"সহজ ভাষায়"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Fluency & Coherence"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"FC"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"থেমে না গিয়ে, গুছিয়ে, যথেষ্ট লম্বা করে বলতে পারো?"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Lexical Resource"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"LR"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"যা বোঝাতে চাও তার জন্য সঠিক শব্দ আছে? বৈচিত্র্য আছে?"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Grammatical Range & Accuracy"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"GRA"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"নানা ধরনের বাক্য বলো? ভুল কত কম?"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Pronunciation"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"P"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"তোমাকে সহজে বোঝা যায়? শব্দে জোর ও সুর ঠিক আছে?"}]}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"২.১ Fluency & Coherence — সবচেয়ে বেশি ভুল বোঝা criterion"}]},{"type":"paragraph","content":[{"type":"text","text":"Fluency মানে দ্রুত বলা নয়। দ্রুত বলতে গিয়ে অস্পষ্ট হয়ে গেলে বরং নম্বর কমে। Fluency মানে:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"যথেষ্ট লম্বা করে বলা (speak at length) — এক-দুই শব্দে থেমে না যাওয়া"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ভাষার কারণে না থামা — চিন্তা করার জন্য থামা স্বাভাবিক, শব্দ খুঁজতে গিয়ে থামা নয়"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"অতিরিক্ত self-correction না করা — বারবার \"sorry, I mean...\" বললে প্রবাহ ভাঙে"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Coherence — কথাগুলো যৌক্তিক ক্রমে আসছে, এলোমেলো নয়"}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Band 6-এ আটকে থাকার এক নম্বর কারণ উত্তর খুব ছোট। Part 1-এ ৩-৫ শব্দের উত্তর দিলে examiner তোমার ভাষা মাপার মতো উপাদানই পান না, ফলে তিনি নিরাপদ দিকে থেকে ৫ বা ৬ দেন। প্রতিটি উত্তরে অন্তত ২–৪টি বাক্য বলো — এই একটি অভ্যাসই অনেকের FC ০.৫–১.০ ব্যান্ড বাড়িয়ে দেয়।"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"২.২ Lexical Resource"}]},{"type":"paragraph","content":[{"type":"text","text":"LR মাপে চারটি জিনিস: বৈচিত্র্য, নির্ভুলতা, collocation এবং paraphrase করার ক্ষমতা (শব্দ মনে না পড়লে ঘুরিয়ে বলতে পারা)।"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Band"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"যেমন শোনায়"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৫"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"সীমিত শব্দ; বারবার একই শব্দ; সঠিক শব্দ না পেয়ে থেমে যাওয়া"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৬"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"যথেষ্ট শব্দ কিন্তু সাধারণ; very good, very important, nice; কিছু ভুল ব্যবহার"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৭"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"নমনীয় ব্যবহার; কিছু কম-প্রচলিত ও idiomatic শব্দ; সচেতন collocation; কার্যকর paraphrase"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৮"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"বিস্তৃত ও সাবলীল; বিরল শব্দ সঠিক ও স্বাভাবিক জায়গায়; শৈলী সম্পর্কে সচেতনতা"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"লক্ষ করো, Band 7-এর সংজ্ঞাতেই \"some less common and idiomatic vocabulary\" কথাটি আছে। মানে ৭ পেতে হলে শুধু নির্ভুল হলে হবে না — কিছু স্বাভাবিক, কথ্য ইংরেজি বাক্যাংশ ব্যবহার করতেই হবে (অধ্যায় ৯)।"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"২.৩ Grammatical Range & Accuracy"}]},{"type":"paragraph","content":[{"type":"text","text":"দুটো জিনিস একসাথে: বৈচিত্র্য ও নির্ভুলতা। শুধু নির্ভুল simple বাক্য বললে ৬-এর উপরে ওঠা যায় না।"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Band"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"বাক্য গঠন"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"ভুল"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৫"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"প্রায় সবই simple; complex চেষ্টা করলে ভেঙে যায়"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ঘন ঘন, মাঝে মাঝে অর্থ বোঝা কঠিন"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৬"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"simple + কিছু complex"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ভুল আছে কিন্তু অর্থ বোঝা যায়"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৭"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"নানা ধরনের complex কাঠামো, কিছুটা নমনীয়ভাবে"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অনেক বাক্য সম্পূর্ণ নির্ভুল; কিছু ভুল থেকে যায়"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৮"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"বেশিরভাগ বাক্য নির্ভুল; বৈচিত্র্য স্বাভাবিক"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"বিরল, খুব ছোট ভুল"}]}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"২.৪ Pronunciation — যা মাপা হয় এবং যা হয় না"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"সবচেয়ে বড় ভুল ধারণা Accent-এ কোনো নম্বর নেই। বাঙালি accent নিয়ে Band 9 পাওয়া সম্ভব। যা মাপা হয় তা হলো intelligibility — শ্রোতার তোমাকে বুঝতে কতটা পরিশ্রম করতে হয়।"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Pronunciation-এর চারটি উপাদান:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Individual sounds — নির্দিষ্ট ধ্বনি স্পষ্ট কিনা (v/w, s/sh, z/j — অধ্যায় ১৪)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Word stress — শব্দের কোন syllable-এ জোর (PHO-to-graph বনাম pho-TO-gra-phy)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sentence stress & rhythm — বাক্যের কোন শব্দে জোর"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Intonation — কণ্ঠের ওঠানামা; একঘেয়ে সুরে বললে নম্বর কমে"}]}]}]}]}'::jsonb, 'published', 'advanced', 10, now());

  -- Band 5 vs 6 vs 7 vs 8: The Real Differences
  insert into lessons (node_id, title, slug, excerpt, content, status, difficulty, estimated_minutes, published_at)
  values (v_foundations, 'Band 5 vs 6 vs 7 vs 8: The Real Differences', 'band-5-to-8-differences', 'The same question, answered at four different bands -- and what actually changes between them.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অধ্যায় ৩ — Band 5, 6, 7, 8: আসল পার্থক্য"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Criterion"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Band 5"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Band 6"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Band 7"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Band 8"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Fluency & Coherence"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ছোট উত্তর; ঘন ঘন থামা; পুনরাবৃত্তি; সরল সংযোগ"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"কথা চালিয়ে যায় কিন্তু হোঁচট খায়; কিছু self-correction; সরল linking"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"সহজে দীর্ঘ কথা বলে; মাঝে মাঝে ভাষাগত দ্বিধা; নানা discourse marker"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"সাবলীল ও অনায়াস; দ্বিধা থাকলে তা বিষয়বস্তুর কারণে, ভাষার নয়"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Lexical Resource"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"সীমিত; শব্দ খুঁজে না পেয়ে থেমে যায়"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"যথেষ্ট কিন্তু সাধারণ; কিছু ভুল ব্যবহার"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"নমনীয়; কিছু idiomatic ও কম-প্রচলিত শব্দ; ভালো paraphrase"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"বিস্তৃত ও নির্ভুল; স্বাভাবিক শৈলীবোধ"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Grammar"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"প্রায় সবই simple; ঘন ঘন ভুল"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"কিছু complex; ভুল আছে"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"নানা কাঠামো; অনেক বাক্য নির্ভুল"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"বেশিরভাগ নির্ভুল; বৈচিত্র্য স্বাভাবিক"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Pronunciation"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"বোঝা যায় কিন্তু শ্রোতাকে পরিশ্রম করতে হয়"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"সাধারণত বোঝা যায়; কিছু শব্দ অস্পষ্ট"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"নানা বৈশিষ্ট্য নিয়ন্ত্রণে; সাধারণত সহজে বোঝা যায়"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"সর্বত্র সহজে বোধগম্য; মাতৃভাষার প্রভাব ন্যূনতম"}]}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৩.১ ৫ → ৬.৫ : তিনটি পরিবর্তন"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"উত্তর লম্বা করো। প্রতিটি উত্তরে কারণ ও উদাহরণ যোগ করো (অধ্যায় ৫)।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"থামা বন্ধ করো। বাংলা ফিলার (\"মানে\", \"আসলে\") বাদ দিয়ে ইংরেজি stalling phrase ব্যবহার করো (অধ্যায় ৭)।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"\"very + সাধারণ শব্দ\" ছাড়ো। very good → absolutely brilliant; very tired → exhausted।"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৩.২ ৬.৫ → ৭.৫ : তিনটি পরিবর্তন"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Idiomatic ভাষা যোগ করো — Band 7-এর সরাসরি শর্ত (অধ্যায় ৯)।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Complex বাক্য নির্ভুলভাবে বলো — বিশেষ করে conditional, relative clause ও present perfect (অধ্যায় ১১)।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"মতামতে nuance আনো — It depends, To some extent, I would say it is more about... (অধ্যায় ৬ ও ১৮)।"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৩.৩ একই প্রশ্ন, চারটি ব্যান্ড"}]},{"type":"paragraph","content":[{"type":"text","text":"প্রশ্ন: \"Do you enjoy cooking?\""}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Band"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"উত্তর"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"সমস্যা / শক্তি"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"~৫"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Yes. I like cooking. It is very good."}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"তিনটি ছোট বাক্য; কোনো ব্যাখ্যা নেই; examiner মাপার কিছুই পেলেন না"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"~৬"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Yes, I like cooking. I usually cook rice and curry on the weekend because I have more time. It is very relaxing for me."}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ঠিক আছে, কারণও আছে — কিন্তু ভাষা সাধারণ, কাঠামো একঘেয়ে"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"~৭"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"I do, actually — more than I expected to. I only started during the pandemic, but now I cook most weekends, usually something slow like a beef curry. I find it quite therapeutic after a long week at work."}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"স্বাভাবিক শুরু, নির্দিষ্ট বিবরণ, ভালো শব্দ (therapeutic), বৈচিত্র্যময় বাক্য"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"~৮"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"I''ve really grown to love it, yes. I was hopeless in the kitchen until a few years ago, but once I got the hang of a few basics it became something I actually look forward to. There''s something genuinely satisfying about spending two hours on a curry and watching people demolish it in ten minutes."}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অনায়াস প্রবাহ; idiomatic (got the hang of, hopeless in the kitchen, demolish it); হাস্যরস; নিখুঁত কাঠামো"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"লক্ষ করো — Band 8 উত্তরে একটিও \"কঠিন\" শব্দ নেই। আছে স্বাভাবিকতা, নির্দিষ্টতা আর ব্যক্তিত্ব। এটাই Speaking-এ ৮ পাওয়ার আসল রহস্য।"}]},{"type":"paragraph","content":[{"type":"text","text":"Fluency & Coherence"}]},{"type":"paragraph","content":[{"type":"text","text":"উত্তর লম্বা করা, থেমে না যাওয়া, এবং গুছিয়ে বলা"}]}]}'::jsonb, 'published', 'advanced', 10, now());

  -- What Fluency Really Means
  insert into lessons (node_id, title, slug, excerpt, content, status, difficulty, estimated_minutes, published_at)
  values (v_foundations, 'What Fluency Really Means', 'what-fluency-really-means', 'The four parts of fluency, the two kinds of pausing, and the Bangla filler words that quietly cost you marks.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অধ্যায় ৪ — Fluency আসলে কী (এবং কী নয়)"}]},{"type":"paragraph","content":[{"type":"text","text":"শিক্ষার্থীরা fluency-কে \"দ্রুত বলা\" ভাবে, তাই দ্রুত বলতে গিয়ে অস্পষ্ট হয়ে যায় এবং Pronunciation-এ নম্বর হারায়। বাস্তবে examiner চারটি জিনিস শোনেন।"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৪.১ Fluency-র চারটি উপাদান"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"উপাদান"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"কী মাপা হয়"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Band 7-এর মান"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Length"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"তুমি কত লম্বা করে বলতে পারো"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Part 1-এ ২–৪ বাক্য, Part 3-এ ৪–৬ বাক্য, Part 2-এ ২ মিনিট"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Hesitation"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"কত ঘন ঘন ও কেন থামো"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"থামা যায়, কিন্তু ভাষা খুঁজতে গিয়ে নয়"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Self-correction"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"কতবার নিজেকে শুধরাও"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"মাঝে মাঝে ঠিক আছে; ঘন ঘন হলে প্রবাহ ভাঙে"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Coherence"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"যুক্তির ক্রম ও সংযোগ"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"শ্রোতা কোথাও হারিয়ে যান না"}]}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৪.২ দুই ধরনের থামা — একটি ক্ষতিকর, একটি নয়"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"ধরন"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"উদাহরণ"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"নম্বরে প্রভাব"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Content hesitation (ভাবছি কী বলব)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"\"Hmm, that''s an interesting question — let me think for a second.\""}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"✅ কোনো ক্ষতি নেই; বরং স্বাভাবিক ও পরিণত শোনায়"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Language hesitation (শব্দ খুঁজছি)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"\"I want to... the... how do you say... the thing that...\""}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"❌ সরাসরি FC-তে আঘাত"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"কৌশলটা সহজ: language hesitation-কে content hesitation-এ রূপান্তর করো। শব্দ খুঁজে না পেলে চুপ না থেকে বলো — এবং ঘুরিয়ে বলো (paraphrase)।"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"হেসিটেশন সামলানো ❌ যা হয়: \"In my city there is a lot of... [৪ সেকেন্ড নীরবতা] ... আসলে... traffic jam.\"  ✅ যা করা উচিত: \"In my city there''s a lot of — well, I suppose the best word is congestion. It takes me nearly an hour to travel about six kilometres.\""}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৪.৩ বাংলা ফিলার — নীরব ঘাতক"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"সবচেয়ে বেশি নম্বর কাটে যেখানে চাপের মধ্যে বাংলা ফিলার বেরিয়ে আসে: \"মানে\", \"আসলে\", \"কী যেন\", \"ইয়ে\"। প্রতিটি বাংলা শব্দ examiner-এর কাছে ভাষার নিয়ন্ত্রণ হারানোর সংকেত। এর সমাধান নীরব থাকা নয় — ইংরেজি বিকল্প অভ্যাসে আনা।"}]}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"বাংলা ফিলার"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"ইংরেজি বিকল্প (নিরাপদ ও স্বাভাবিক)"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"মানে... / আসলে..."}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"I mean... / Actually... / What I''m trying to say is..."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"কী যেন..."}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"What''s the word... / I can''t think of the exact term, but..."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ইয়ে... / উম..."}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Well... / Let me see... / Right, so..."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"(দীর্ঘ নীরবতা)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"That''s a good question, actually. / I haven''t really thought about that before."}]}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"অনুশীলন আগামী ৭ দিন প্রতিদিন ২ মিনিট যেকোনো বিষয়ে একটানা ইংরেজিতে বলো এবং রেকর্ড করো। শুনে প্রতিটি বাংলা শব্দ গুনে রাখো। প্রথম দিন হয়তো ১২টি হবে, সপ্তম দিনে ২টি। সফলতার সংকেত: যখন থেমে যাওয়ার মুহূর্তে মুখ থেকে স্বয়ংক্রিয়ভাবে \"Well...\" বেরোবে, \"মানে\" নয়।"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৪.৪ গতি ও বিরতি"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"খুব দ্রুত বোলো না। আদর্শ গতি মিনিটে ১২০–১৫০ শব্দ — অর্থাৎ স্বাভাবিক কথোপকথনের গতি।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"অর্থপূর্ণ জায়গায় থামো — বাক্যের শেষে বা comma-র জায়গায়, শব্দের মাঝখানে নয়।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"থামা মানেই দুর্বলতা নয়। সঠিক জায়গায় ছোট বিরতি বরং আত্মবিশ্বাসী শোনায়।"}]}]}]}]}'::jsonb, 'published', 'advanced', 10, now());

  -- Three Engines to Extend Your Answers
  insert into lessons (node_id, title, slug, excerpt, content, status, difficulty, estimated_minutes, published_at)
  values (v_foundations, 'Three Engines to Extend Your Answers', 'three-engines-to-extend-answers', 'PREP, Time Travel, and Contrast -- three reliable ways to speak longer without padding.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অধ্যায় ৫ — উত্তর লম্বা করার তিনটি ইঞ্জিন"}]},{"type":"paragraph","content":[{"type":"text","text":"\"আমি বেশি কথা বলতে পারি না\" — এই সমস্যাটা ইংরেজির নয়, কাঠামোর। নিচের তিনটি ইঞ্জিন যেকোনো প্রশ্নে কাজ করে এবং যেকোনো ছোট উত্তরকে সাথে সাথে দ্বিগুণ-তিনগুণ করে দেয়।"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৫.১ Engine 1 — PREP (সবচেয়ে বহুমুখী)"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"অক্ষর"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"মানে"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"উদাহরণ বাক্য"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"P"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Point — সরাসরি উত্তর"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Yes, I''m quite into photography."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"R"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Reason — কেন"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Mainly because it forces me to notice things I''d normally walk straight past."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"E"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Example — উদাহরণ"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Last month I spent an entire morning photographing an old building near my house that I''d passed for years without looking at properly."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"P"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Point — ঘুরে আসা / সম্প্রসারণ"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"So yes, it''s become a bit of an obsession, really."}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"চার ধাপে একটি এক-শব্দের উত্তর একটি পূর্ণ, স্বাভাবিক উত্তরে পরিণত হলো — এবং examiner তোমার grammar, vocabulary ও pronunciation তিনটাই মাপার সুযোগ পেলেন।"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৫.২ Engine 2 — Time Travel (অতীত / বর্তমান / ভবিষ্যৎ)"}]},{"type":"paragraph","content":[{"type":"text","text":"যেকোনো বিষয়ে তিনটি সময়ে ভাবো। এটি একই সাথে grammar-এর বৈচিত্র্যও দেখায় — একটি সিদ্ধান্তে দুটি criterion-এ লাভ।"}]},{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":": \"I used to read a lot as a teenager — mostly detective novels I borrowed from my uncle.\" বর্তমান: \"These days I read far less than I''d like to, mainly because of work, though I still get through a book a month or so.\" ভবিষ্যৎ: \"I''m hoping to get back into it properly once things calm down — I''ve got a stack of books sitting there waiting.\"","label":"🔊 Listen to this answer"}}]},{"type":"paragraph","content":[{"type":"text","text":"Time Travel Engine প্রশ্ন: Do you like reading?  অতীত: \"I used to read a lot as a teenager — mostly detective novels I borrowed from my uncle.\" বর্তমান: \"These days I read far less than I''d like to, mainly because of work, though I still get through a book a month or so.\" ভবিষ্যৎ: \"I''m hoping to get back into it properly once things calm down — I''ve got a stack of books sitting there waiting.\""}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"কেন এটা এত শক্তিশালী একটি উত্তরে তুমি ব্যবহার করলে: used to (past habit), present simple, present perfect, be hoping to (future intention), ''d like to (conditional)। এটাই \"a range of complex structures\" — Band 7-এর সংজ্ঞা।"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৫.৩ Engine 3 — Contrast (তুলনা ও ব্যতিক্রম)"}]},{"type":"paragraph","content":[{"type":"text","text":"নিজের উত্তরের বিপরীত দিকটা যোগ করো। এটি উত্তরকে পরিণত ও ভারসাম্যপূর্ণ করে — Band 7+ এর স্পষ্ট চিহ্ন।"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"কাঠামো"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"উদাহরণ"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ব্যতিক্রম যোগ করা"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"\"I generally prefer city life, although I do miss the quiet when I visit my grandparents'' village.\""}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"তুলনা করা"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"\"Compared to when I was a student, I have far less free time now.\""}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"শর্ত দেওয়া"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"\"It really depends on the day — if I''ve had a stressful week, I just want to stay in.\""}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অন্য মানুষের সাথে তুলনা"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"\"Most of my friends are obsessed with cricket, whereas I''ve never really got into it.\""}]}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৫.৪ কতটা লম্বা — অংশভিত্তিক লক্ষ্য"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"অংশ"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"উত্তরের দৈর্ঘ্য"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"কেন"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Part 1"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"২–৪ বাক্য (১৫–৩০ সেকেন্ড)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"খুব ছোট = মাপার উপাদান নেই; খুব লম্বা = examiner থামিয়ে দেবেন"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Part 2"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"১.৫–২ মিনিট একটানা"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"পুরো সময় ব্যবহার করা বাধ্যতামূলক; আগে থেমে গেলে FC-তে ক্ষতি"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Part 3"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৪–৬ বাক্য (৩০–৪৫ সেকেন্ড)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"এখানে যুক্তি ও বিশ্লেষণ দেখাতে হয়, তাই লম্বা"}]}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"অতিরিক্ত লম্বা উত্তরের বিপদ Part 1-এ ৯০ সেকেন্ড বলা ভালো নয় — এটি প্রশ্নের ধরনের সাথে বেমানান এবং প্রায়ই মুখস্থ শোনায়। Examiner থামিয়ে দিলে সেটি একটি সতর্কসংকেত। প্রশ্নের আকার অনুযায়ী উত্তরের আকার — এটিও coherence-এর অংশ।"}]}]}]}'::jsonb, 'published', 'advanced', 12, now());

  -- Coherence in Spoken English
  insert into lessons (node_id, title, slug, excerpt, content, status, difficulty, estimated_minutes, published_at)
  values (v_foundations, 'Coherence in Spoken English', 'coherence-in-spoken-english', 'Spoken vs. written linking, three ways coherence breaks down, and staying on topic.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অধ্যায় ৬ — Coherence: কথ্য ইংরেজির সংযোগ"}]},{"type":"paragraph","content":[{"type":"text","text":"লেখার linking word আর কথার linking word এক নয়। \"Moreover\", \"Furthermore\", \"In addition\" — এগুলো কথায় ব্যবহার করলে বইয়ের মতো কৃত্রিম শোনায় এবং examiner সন্দেহ করেন যে উত্তরটি মুখস্থ।"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৬.১ কথ্য বনাম লিখিত সংযোগ"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"কাজ"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"❌ লিখিত (কথায় কৃত্রিম)"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"✅ কথ্য (স্বাভাবিক)"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"যোগ করা"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Moreover, Furthermore, In addition"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"And another thing is... • Plus... • On top of that..."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"বিপরীত"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"However, Nevertheless, Conversely"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"But then again... • That said... • Having said that... • Mind you..."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"কারণ"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Therefore, Consequently, Hence"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"So... • That''s why... • Which is why..."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"উদাহরণ"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"For instance, To illustrate"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Like... • For example... • Take my brother — he..."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"মতামত"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"In my opinion, From my perspective"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"I''d say... • Personally... • If you ask me... • I reckon..."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"শুরু করা"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Firstly, To begin with"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Well... • Right, so... • The main thing is..."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"শেষ করা"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"In conclusion, To sum up"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"So yeah... • That''s pretty much it. • Something like that."}]}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"একটি সূক্ষ্ম কিন্তু গুরুত্বপূর্ণ বিষয় IELTS Speaking-এ অনানুষ্ঠানিক ভাষা নিষিদ্ধ নয় — বরং প্রত্যাশিত। এটি একটি কথোপকথন, প্রবন্ধ নয়। I reckon, sort of, pretty much, a bit — এগুলো Band 7-8-এর স্বাভাবিক লক্ষণ। তবে slang নয় (gonna, wanna, dude) — এগুলো এড়াও।"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৬.২ Coherence ভাঙার তিনটি উপায়"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"প্রশ্নের উত্তর না দেওয়া। \"Do you prefer books or films?\" → সরাসরি একটা বেছে নাও, তারপর ব্যাখ্যা করো। উত্তর না দিয়ে ঘুরিয়ে বললে examiner লক্ষ করেন।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"বিষয় থেকে সরে যাওয়া। শুরু করলে \"my hometown\" নিয়ে, শেষ করলে \"my cousin''s wedding\" নিয়ে।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"মুখস্থ উত্তর জোর করে ঢোকানো। সবচেয়ে বড় coherence-হত্যাকারী — প্রশ্ন যাই হোক, তুমি তোমার তৈরি করা প্যারাটা বলে দিলে শ্রোতা টের পান।"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৬.৩ প্রশ্নের সাথে যুক্ত থাকার সূত্র"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"প্রশ্ন → সরাসরি উত্তর → কারণ → উদাহরণ প্রশ্ন: Why do you think some people don''t like sport?  ✅ সরাসরি যুক্ত: \"I think a lot of it comes down to school experiences, actually. If you were always the last one picked for a team, you probably grew up associating sport with humiliation rather than fun. My younger brother is exactly like that — he''s fit and healthy, but he won''t go near a football pitch.\""}]}]}]}'::jsonb, 'published', 'advanced', 8, now());

  -- Recovery Toolkit: What to Say When You Get Stuck
  insert into lessons (node_id, title, slug, excerpt, content, status, difficulty, estimated_minutes, published_at)
  values (v_foundations, 'Recovery Toolkit: What to Say When You Get Stuck', 'recovery-toolkit', 'Stalling phrases, paraphrasing when a word won''t come, and what to do if you don''t understand the question.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অধ্যায় ৭ — থেমে গেলে কী করবে: Recovery Toolkit"}]},{"type":"paragraph","content":[{"type":"text","text":"পরীক্ষায় সবাই আটকায় — Band 9 প্রার্থীও। পার্থক্য হলো আটকে যাওয়ার পর কী করো। এই অধ্যায়ের বাক্যগুলো মুখস্থ করার মতো — কারণ এগুলো উত্তর নয়, যন্ত্রপাতি।"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৭.১ সময় কেনার বাক্য (Stalling)"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"পরিস্থিতি"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"ব্যবহারযোগ্য বাক্য"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ভাবার সময় দরকার"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"\"That''s a really interesting question.\" • \"I''ve never actually thought about that before.\" • \"Let me think about that for a second.\""}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"প্রশ্নটা কঠিন"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"\"That''s quite a difficult one to answer.\" • \"There are probably several ways of looking at this.\""}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"শুরু করতে চাও"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"\"Well, off the top of my head...\" • \"I suppose the first thing that comes to mind is...\""}]}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"সতর্কতা এই বাক্যগুলো একবার বা দুইবার ব্যবহার করো, প্রতিটি প্রশ্নে নয়। প্রতিবার \"That''s an interesting question\" বললে সেটি মুখস্থ কৌশল হিসেবে ধরা পড়ে এবং উল্টো ক্ষতি করে।"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৭.২ শব্দ মনে না পড়লে — Paraphrase Strategy"}]},{"type":"paragraph","content":[{"type":"text","text":"এটি Band 7-এর সরাসরি সংজ্ঞার অংশ: \"uses paraphrase effectively\"। শব্দ না জানা কোনো সমস্যা নয়; ঘুরিয়ে বলতে না পারাই সমস্যা।"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"কৌশল"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"উদাহরণ (শব্দ: `stethoscope`)"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"কাজ দিয়ে বর্ণনা"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"\"the thing doctors use to listen to your heartbeat\""}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"চেহারা দিয়ে বর্ণনা"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"\"a sort of tube with two earpieces\""}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"সাধারণীকরণ"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"\"a piece of medical equipment\""}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"স্বীকার করে এগিয়ে যাওয়া"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"\"I can''t remember what it''s called in English, but it''s the device doctors put on your chest.\""}]}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"এটাই আসল দক্ষতা Examiner কখনোই শব্দ ভুলে যাওয়ার জন্য নম্বর কাটেন না। কিন্তু তুমি যদি চুপ করে যাও বা বাংলা বলে ফেলো, তখন কাটেন। শব্দ ভুলে যাওয়াকে দক্ষতা প্রদর্শনের সুযোগে পরিণত করো।"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৭.৩ প্রশ্ন বুঝতে না পারলে"}]},{"type":"paragraph","content":[{"type":"text","text":"এটি সম্পূর্ণ বৈধ এবং কোনো নম্বর কাটে না:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"\"Sorry, could you repeat that, please?\""}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"\"I''m not sure I follow — do you mean ... ?\""}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"\"Could you rephrase the question, please?\""}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Part 1 ও 3-এ examiner প্রশ্ন পুনরাবৃত্তি বা ব্যাখ্যা করতে পারেন। Part 2-এ cue card পড়ে দেওয়া হয় না — কার্ডটি তোমার হাতেই থাকে, তাই বারবার পড়তে পারো।"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"যা কখনো করবে না ❌ \"Pardon?\" বারবার বলা — একবার ঠিক আছে, তিনবার হলে শোনার সমস্যা মনে হয়। ❌ প্রশ্ন না বুঝে অনুমান করে উত্তর দেওয়া — ভুল বিষয়ে ২ মিনিট বললে Task-সংক্রান্ত ক্ষতি হয়। ❌ \"I don''t know\" বলে থেমে যাওয়া — বদলে বলো: \"I''m not particularly familiar with this, but I''d imagine that...\" এবং কিছু একটা যুক্তি দাঁড় করাও। অজ্ঞতা সমস্যা নয়, নীরবতা সমস্যা।"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৭.৪ মাঝপথে আটকে গেলে"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"মাঝপথে পুনরুদ্ধার ❌ যা হয়: \"...and the government should, um... [৬ সেকেন্ড নীরবতা] ...sorry.\"  ✅ যা করবে: \"...and the government should — actually, let me put that differently. What I mean is that the responsibility lies more with local authorities than with the central government.\""}]}]},{"type":"paragraph","content":[{"type":"text","text":"মূল কৌশল: কখনো \"sorry\" বলে থেমো না — \"let me put that differently\" বলে চালিয়ে যাও। প্রথমটি ব্যর্থতা, দ্বিতীয়টি দক্ষতা।"}]},{"type":"paragraph","content":[{"type":"text","text":"Lexical Resource"}]},{"type":"paragraph","content":[{"type":"text","text":"কঠিন শব্দ নয় — স্বাভাবিক, নির্ভুল, নমনীয় ভাষা"}]}]}'::jsonb, 'published', 'advanced', 10, now());

  -- Speaking Vocabulary: Different Rules
  insert into lessons (node_id, title, slug, excerpt, content, status, difficulty, estimated_minutes, published_at)
  values (v_foundations, 'Speaking Vocabulary: Different Rules', 'speaking-vocabulary-different-rules', 'What "good vocabulary" means in Speaking, breaking the "very + basic word" habit, and collocation.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অধ্যায় ৮ — Speaking-এ শব্দভাণ্ডার: নিয়ম আলাদা"}]},{"type":"paragraph","content":[{"type":"text","text":"Writing-এ যে শব্দ নম্বর বাড়ায়, Speaking-এ সেটাই নম্বর কমাতে পারে। কথা বলার সময় Furthermore, this phenomenon is ubiquitous বললে examiner ভাবেন \"এটা মুখস্থ\" — এবং সন্দেহ একবার জন্মালে পুরো পরীক্ষায় ক্ষতি হয়।"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৮.১ Speaking-এ ভালো শব্দভাণ্ডার মানে কী"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"❌ ভুল ধারণা"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"✅ বাস্তবতা"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"কঠিন, দীর্ঘ শব্দ বেশি নম্বর দেয়"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ভুল জায়গায় বসানো কঠিন শব্দ নম্বর কমায়"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Academic শব্দ ব্যবহার করতে হবে"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Speaking-এ কথ্য ও স্বাভাবিক ভাষাই প্রত্যাশিত"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"একই শব্দ দুইবার বলা যাবে না"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"স্বাভাবিক পুনরাবৃত্তি গ্রহণযোগ্য; কৃত্রিম synonym বরং খারাপ"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Idiom মানেই ভালো"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"সঠিক ও প্রাসঙ্গিক idiom ভালো; জোর করে ঢোকানো idiom বিপর্যয়"}]}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৮.২ \"very + সাধারণ শব্দ\" থেকে মুক্তি"}]},{"type":"paragraph","content":[{"type":"text","text":"বাংলাদেশি শিক্ষার্থীদের সবচেয়ে বড় LR-দুর্বলতা: সবকিছু \"very\" দিয়ে। একটি শব্দ বদলালেই বাক্যটা এক ধাপ উপরে উঠে যায়।"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"❌ Band 5–6"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"✅ Band 7+"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"❌ Band 5–6"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"✅ Band 7+"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"very good"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"brilliant / superb / outstanding"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"very tired"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"exhausted / worn out"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"very bad"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"awful / dreadful / terrible"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"very hungry"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"starving / famished"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"very big"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"enormous / huge / massive"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"very small"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"tiny / minuscule"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"very interesting"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"fascinating / gripping"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"very happy"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"delighted / thrilled / over the moon"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"very difficult"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"demanding / challenging / tough"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"very beautiful"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"stunning / gorgeous / breathtaking"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"very important"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"crucial / vital / essential"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"very crowded"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"packed / heaving / jam-packed"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"very expensive"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"pricey / steep / extortionate"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"very cold"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"freezing / bitterly cold"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"very angry"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"furious / livid"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"very surprised"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"astonished / taken aback"}]}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৮.৩ Collocation — যে শব্দগুলো একসাথে বসে"}]},{"type":"paragraph","content":[{"type":"text","text":"Band 7-এর সংজ্ঞায় সরাসরি বলা আছে \"awareness of collocation\"। কয়েকটি যা প্রায় প্রতিটি Speaking পরীক্ষায় কাজে লাগে:"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"ক্ষেত্র"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Collocation"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"সময় ও অভ্যাস"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"spend time (doing) • kill time • make time for • have a busy schedule • get into the habit of"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"পছন্দ-অপছন্দ"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"be really into • be keen on • can''t stand • not my cup of tea • have a soft spot for"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"কাজ ও পড়াশোনা"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"meet a deadline • take a course • do research • pull an all-nighter • strike a balance between"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"সম্পর্ক"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"get on well with • keep in touch • lose touch • have a lot in common • drift apart"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"সমস্যা"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"face a challenge • come up against • sort something out • deal with • take its toll on"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"আবেগ"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"be over the moon • be gutted • take it in your stride • get on my nerves"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"মতামত"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"have mixed feelings about • be in two minds • come round to the idea • see the point of"}]}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৮.৪ Paraphrase — Band 7-এর সরাসরি শর্ত"}]},{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ৭-এ কৌশলটা দেখেছ। এখানে অনুশীলনের একটি নিয়ম: প্রতিদিন ৫টি বাংলা শব্দ নাও যার ইংরেজি তুমি জানো না, এবং প্রতিটি ইংরেজিতে ঘুরিয়ে বলার অনুশীলন করো। এই একটি অভ্যাস পরীক্ষায় আটকে যাওয়ার ভয় প্রায় পুরোপুরি দূর করে দেয়।"}]}]}'::jsonb, 'published', 'advanced', 8, now());

  -- Idiomatic Language: The Key to Band 7
  insert into lessons (node_id, title, slug, excerpt, content, status, difficulty, estimated_minutes, published_at)
  values (v_foundations, 'Idiomatic Language: The Key to Band 7', 'idiomatic-language-key-to-band-7', 'The safe kind of idiom vs. the risky kind, and 35 natural idiomatic phrases you can actually use.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অধ্যায় ৯ — Idiomatic Language: Band 7-এর চাবি"}]},{"type":"paragraph","content":[{"type":"text","text":"Band 7-এর official বর্ণনায় লেখা আছে: \"uses some less common and idiomatic vocabulary\"। মানে idiomatic ভাষা ছাড়া ৭ পাওয়া কঠিন। কিন্তু এখানেই সবচেয়ে বেশি শিক্ষার্থী ভুল করে।"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৯.১ দুই ধরনের idiom — একটি নিরাপদ, একটি বিপজ্জনক"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"ধরন"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"উদাহরণ"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"রায়"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Everyday idiomatic phrases (নিরাপদ)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"to be into something • to get the hang of • to be worn out • a bit of a nightmare • to be on the fence"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"✅ স্বাভাবিক, প্রায় সব প্রসঙ্গে খাটে — এগুলোই ব্যবহার করো"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Proverb-জাতীয় idiom (বিপজ্জনক)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"It''s raining cats and dogs • Every cloud has a silver lining • A piece of cake • Bite the bullet"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"⚠️ কৃত্রিম ও শিখে-বলা শোনায়; native speaker কথায় এগুলো খুব কমই বলেন"}]}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"কেন Proverb-জাতীয় idiom বিপজ্জনক শিক্ষার্থীরা কোচিং থেকে ২০টি idiom মুখস্থ করে জোর করে ঢুকিয়ে দেয় — \"In my hometown, it is raining cats and dogs in monsoon.\" কথাটা ব্যাকরণগতভাবে ঠিক, কিন্তু কেউ এভাবে কথা বলে না। Examiner এটিকে মুখস্থ ভাষা হিসেবে চিহ্নিত করেন, এবং LR বাড়ার বদলে কমে।"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৯.২ ৩৫টি নিরাপদ, স্বাভাবিক Idiomatic Phrase"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"বিষয়"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"শব্দবন্ধ ও অর্থ"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"আগ্রহ"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"be into (আগ্রহী) • be hooked on (আসক্ত) • not my thing (আমার পছন্দ নয়) • have a soft spot for (দুর্বলতা আছে)"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"দক্ষতা"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"get the hang of (আয়ত্ত করা) • pick something up (শিখে ফেলা) • be hopeless at (একদম পারি না) • have a knack for (স্বাভাবিক দক্ষতা)"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"সময়"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"now and then (মাঝে মাঝে) • around the clock (সারাক্ষণ) • at the last minute (একদম শেষে) • in the long run (দীর্ঘমেয়াদে)"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"কষ্ট"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"a bit of a nightmare (খুব ঝামেলার) • an uphill battle (কঠিন লড়াই) • take its toll on (ক্ষতি করা) • be swamped with (কাজের চাপে ডুবে থাকা)"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"মতামত"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"be on the fence (সিদ্ধান্তহীন) • I''d go so far as to say (এমনকি বলব) • it''s a mixed bag (ভালো-মন্দ দুটোই) • there''s no denying that (অস্বীকার করার উপায় নেই)"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"মানুষ"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"get on well with (সদ্ভাব) • see eye to eye (একমত হওয়া) • drift apart (দূরে সরে যাওয়া) • be like chalk and cheese (সম্পূর্ণ আলাদা)"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অবস্থা"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"be worn out (ক্লান্ত) • be over the moon (দারুণ খুশি) • be gutted (খুব হতাশ) • be under the weather (শরীর খারাপ)"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"পরিবর্তন"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"come round to (মত বদলে মেনে নেওয়া) • grow on you (ধীরে ধীরে ভালো লাগা) • get out of hand (নিয়ন্ত্রণের বাইরে যাওয়া)"}]}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"ব্যবহারের সঠিক মাত্রা পুরো ১৪ মিনিটের পরীক্ষায় ৫–৮টি idiomatic phrase যথেষ্ট — অর্থাৎ প্রতি ২ মিনিটে একটি। এর বেশি হলে কৃত্রিম শোনায়। আর যেটির অর্থ ও ব্যবহার নিয়ে তুমি ১০০% নিশ্চিত নও, সেটি ব্যবহার কোরো না।"}]}]}]}'::jsonb, 'published', 'advanced', 10, now());

  -- Topic Vocabulary That Actually Helps
  insert into lessons (node_id, title, slug, excerpt, content, status, difficulty, estimated_minutes, published_at)
  values (v_foundations, 'Topic Vocabulary That Actually Helps', 'topic-vocabulary-that-helps', 'The handful of topics IELTS questions really revolve around, and usable language for each.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অধ্যায় ১০ — টপিক ভোকাবুলারি: যা সত্যিই কাজে লাগে"}]},{"type":"paragraph","content":[{"type":"text","text":"Speaking-এ টপিক অসীম মনে হলেও বাস্তবে প্রশ্ন ঘোরে অল্প কিছু ক্ষেত্রে। নিচের শব্দগুলো বাক্যের ভেতরে শেখো, তালিকা হিসেবে নয়।"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"টপিক"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"ব্যবহারযোগ্য ভাষা"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Hometown / Living"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"be born and raised in • a close-knit community • the outskirts • a bustling city • a stone''s throw from • laid-back"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Work / Study"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"a nine-to-five • a steady job • demanding hours • a steep learning curve • job satisfaction • work my way up"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Free time"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"unwind • wind down • recharge • a change of scene • dabble in • pass the time"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Technology"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"be glued to a screen • cut down on screen time • a lifesaver • constantly notified • digital detox"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Food"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"home-cooked • street food • a comfort food • have a sweet tooth • eat out • grab a bite"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Family & Friends"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"a family gathering • catch up with • grew up together • lean on someone • a lifelong friend"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Travel"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"off the beaten track • a whirlwind trip • soak up the atmosphere • a change of pace • wander around"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Environment"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"cut back on plastic • air quality • green spaces • a throwaway culture • carbon footprint"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Education"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"rote learning • hands-on experience • spoon-feed students • a well-rounded education • cram for exams"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Society & Change"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"a generation gap • the pace of life • cost of living • social mobility • the way things are heading"}]}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"শেখার সঠিক পদ্ধতি শব্দ একা মুখস্থ করলে পরীক্ষায় মনে আসবে না। প্রতিদিন ৫টি শব্দবন্ধ নাও, প্রতিটি দিয়ে একটি বাক্য নিজের জীবন থেকে বানাও, এবং সেই বাক্য জোরে বলো ও রেকর্ড করো। মাসে ১৫০টি শব্দবন্ধ — এবং সেগুলো তোমার নিজের গল্পে বাঁধা, তাই স্বাভাবিকভাবেই মুখে আসবে।"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Grammar"}]},{"type":"paragraph","content":[{"type":"text","text":"কথা বলার সময় যে কাঠামোগুলো সত্যিই লাগে"}]}]}'::jsonb, 'published', 'advanced', 8, now());

  -- Ten Sentence Structures for Speaking
  insert into lessons (node_id, title, slug, excerpt, content, status, difficulty, estimated_minutes, published_at)
  values (v_foundations, 'Ten Sentence Structures for Speaking', 'ten-sentence-structures', 'Ten grammar structures that reliably work in spoken English, and why short sentences matter too.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অধ্যায় ১১ — Speaking-এর ১০টি বাক্যগঠন"}]},{"type":"paragraph","content":[{"type":"text","text":"লেখার grammar আর কথার grammar এক নয়। কথা বলার সময় খুব দীর্ঘ, জটিল বাক্য তৈরি করতে গেলে ভেঙে পড়ার ঝুঁকি বেশি। নিচের ১০টি কাঠামো নির্ভুলভাবে বলতে পারলেই Band 7-এর \"range\" শর্ত পূর্ণ হয়।"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"#"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"কাঠামো"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"উদাহরণ"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"কোথায় লাগে"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"১"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Present perfect"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"I''ve been working there for about three years now."}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"বর্তমান অবস্থা ও অভিজ্ঞতা"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"২"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Used to / would"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"I used to play cricket every evening when I was younger."}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অতীতের অভ্যাস"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৩"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Second conditional"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"If I had more free time, I''d definitely take up photography."}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"কল্পনা ও ইচ্ছা"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৪"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Third conditional"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"If I''d studied engineering, I probably would have ended up somewhere else entirely."}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অতীতের অনুশোচনা"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৫"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Relative clause"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"My uncle, who lives in Chattogram, taught me most of what I know about cooking."}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"বিবরণ যোগ করা"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৬"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Comparative"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"It''s far more convenient than it used to be."}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"তুলনা"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৭"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Modal of speculation"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"It might be because people are simply busier these days."}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Part 3-এ অনুমান"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৮"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Future forms"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"I''m planning to move next year, though I might end up staying."}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"পরিকল্পনা"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৯"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Passive"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"A lot of these decisions are made without consulting local people."}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Part 3-এ সমাজভিত্তিক আলোচনা"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"১০"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Cleft / emphasis"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"What I really enjoy about it is the sense of achievement."}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"জোর দেওয়া — Band 8-এর চিহ্ন"}]}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"বাস্তব লক্ষ্য পুরো পরীক্ষায় এই ১০টির মধ্যে ৬–৭টি ব্যবহার করতে পারলেই যথেষ্ট। সবগুলো ঢোকানোর চেষ্টা কোরো না — জোর করে ঢোকানো conditional শুনলেই বোঝা যায়। বরং অনুশীলনের সময় সচেতনভাবে ব্যবহার করো, যাতে পরীক্ষায় স্বাভাবিকভাবেই বেরিয়ে আসে।"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"১১.১ ছোট বাক্যও দরকার"}]},{"type":"paragraph","content":[{"type":"text","text":"টানা পাঁচটি জটিল বাক্য বললে কৃত্রিম শোনায় এবং ভুলের ঝুঁকি বাড়ে। বৈচিত্র্য মানে জটিল + সরল দুটোই। স্বাভাবিক কথায় ছোট বাক্য থাকেই: \"I love it.\" \"Not really.\" \"It depends.\""}]}]}'::jsonb, 'published', 'advanced', 10, now());

