  insert into lessons (node_id, title, slug, excerpt, content, status, difficulty, estimated_minutes, published_at)
  values (v_foundations, '30 Common Mistakes Bangladeshi Students Make', '30-common-mistakes', 'Grammar errors, Banglish and South Asian English habits, and habitual mistakes that quietly cost marks.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অধ্যায় ১২ — বাংলাদেশি শিক্ষার্থীদের ৩০টি Speaking Mistake"}]},{"type":"paragraph","content":[{"type":"text","text":"এই অধ্যায়টা বইয়ের সবচেয়ে বেশি ROI দেওয়া অংশ। এগুলো এত সাধারণ যে examiner-রা এগুলোকে আলাদা করে চেনেন — এবং ঠিক করা সহজ।"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"১২.১ Grammar ভুল"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"❌ যা বলা হয়"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"✅ যা বলা উচিত"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"I am agree with you."}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"I agree with you."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"I am living here since five years."}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"I''ve been living here for five years."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Yesterday I have gone to Dhaka."}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Yesterday I went to Dhaka."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"One of my friend is a doctor."}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"One of my friends is a doctor."}]}]}]},{"