  insert into lessons (node_id, title, slug, excerpt, content, status, difficulty, estimated_minutes, published_at)
  values (v_foundations, 'What Pronunciation Actually Measures', 'what-pronunciation-measures', 'The four components of the Pronunciation criterion.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অধ্যায় ১৩ — Pronunciation-এ আসলে কী মাপা হয়"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"প্রথমেই ভুল ধারণা দূর করি তোমার বাঙালি accent কোনো সমস্যা নয়। IELTS-এ accent-এর জন্য এক পয়েন্টও কাটা হয় না — ব্রিটিশ, ভারতীয়, নাইজেরিয়ান, বাংলাদেশি, সব accent সমান। যা মাপা হয় তা হলো intelligibility: শ্রোতাকে তোমাকে বুঝতে কতটা পরিশ্রম করতে হয়।"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"১৩.১ চারটি উপাদান"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"উপাদান"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"কী"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"বাংলাদেশি শিক্ষার্থীদের অবস্থা"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Individual sounds"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"নির্দিষ্ট ধ্বনি স্পষ্ট কিনা"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"কিছু নির্দিষ্ট ধ্বনিতে ধারাবাহিক সমস্যা (অধ্যায় ১৪)"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Word stress"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"শব্দের কোন syllable-এ জোর"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"প্রায়ই ভুল — এটি বোধগম্যতায় বড় প্রভাব ফেলে"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Sentence stress / rhythm"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"বাক্যের কোন শব্দে জোর"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"সবচেয়ে বড় দুর্বলতা — সব শব্দে সমান জোর"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Intonation"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"কণ্ঠের ওঠানামা"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"একঘেয়ে, সমতল সুর — Band 6-এ আটকে রাখে"}]}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"১৩.২ কেন rhythm সবচেয়ে গুরুত্বপূর্ণ"}]},{"type":"paragraph","content":[{"type":"text","text":"বাংলা একটি syllable-timed ভাষা — প্রতিটি অক্ষরে মোটামুটি সমান সময় ও জোর পড়ে। ইংরেজি stress-timed — কিছু শব্দে জোর পড়ে, বাকিগুলো দ্রুত ও দুর্বল হয়ে যায়।"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Stress-timed বনাম Syllable-timed বাক্য: I went to the market to buy some vegetables.  ❌ বাংলা ছন্দে (সব সমান): I · WENT · TO · THE · MAR-KET · TO · BUY · SOME · VE-GE-TA-BLES  ✅ ইংরেজি ছন্দে (জোর শুধু গুরুত্বপূর্ণ শব্দে): I WENT to the MARket to BUY some VEgetables  অজোরের শব্দগুলো (to, the, some) দ্রুত ও অস্পষ্ট হয়ে যায় — এটাই স্বাভাবিক ইংরেজি।"}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"একটি অনুশীলন যা সবচেয়ে দ্রুত কাজ করে Shadowing: একটি ইংরেজি অডিও (BBC News, পডকাস্ট, YouTube) চালাও এবং বক্তার ঠিক ০.৫ সেকেন্ড পিছনে থেকে তার সাথে সাথে বলো — শব্দ নয়, সুর ও ছন্দ নকল করো। দিনে ১০ মিনিট, ৩ সপ্তাহ। এটি একক সবচেয়ে কার্যকর pronunciation অনুশীলন, কারণ এতে কান আর মুখ একসাথে প্রশিক্ষিত হয়।"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"১৩.৩ Intonation — কণ্ঠের ওঠানামা"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"পরিস্থিতি"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"সুর"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"উদাহরণ"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"সাধারণ বিবৃতি"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"শেষে নিচে নামে ↘"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"I live in Dhaka. ↘"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Yes/No প্রশ্ন"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"শেষে উপরে ওঠে ↗"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Do you like it? ↗"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"WH প্রশ্ন"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"শেষে নিচে নামে ↘"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Where do you live? ↘"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"তালিকা"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"প্রতিটিতে ওঠে, শেষেরটায় নামে"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"rice ↗, fish ↗, and vegetables ↘"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অনিশ্চয়তা / দ্বিধা"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"সমতল বা সামান্য ওঠে"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Well, I suppose so... →"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"উৎসাহ"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"বড় ওঠানামা"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"It was absolutely brilliant! ↗↘"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"একঘেয়ে সুরে কথা বললে examiner-এর কাছে দুটি বার্তা যায়: আগ্রহহীনতা এবং ভাষার উপর সীমিত নিয়ন্ত্রণ। উৎসাহ দেখানো Speaking-এ সরাসরি নম্বর বাড়ায়।"}]}]}'::jsonb, 'published', 'advanced', 8, now());

  -- Pronunciation Problems for Bangla Speakers
  insert into lessons (node_id, title, slug, excerpt, content, status, difficulty, estimated_minutes, published_at)
  values (v_foundations, 'Pronunciation Problems for Bangla Speakers', 'pronunciation-problems-for-bangla-speakers', 'Seven specific pronunciation issues Bangla speakers run into, and how to fix each one.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অধ্যায় ১৪ — বাংলা-ভাষীদের নির্দিষ্ট উচ্চারণ সমস্যা"}]},{"type":"paragraph","content":[{"type":"text","text":"বাংলা ও ইংরেজির ধ্বনিব্যবস্থা আলাদা, তাই কিছু ভুল প্রায় সব বাংলাদেশি শিক্ষার্থীর হয়। এগুলো নির্দিষ্ট, চিহ্নিত করা যায়, এবং ঠিক করা যায়।"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"১৪.১ সাতটি প্রধান সমস্যা"}]},{"type":"heading","attrs":{"level":4},"content":[{"type":"text","text":"সমস্যা ১ — /v/ বনাম /w/"}]},{"type":"paragraph","content":[{"type":"text","text":"বাংলায় /v/ ধ্বনি নেই, তাই \"very\" → \"wery\", \"video\" → \"widio\" হয়ে যায়।"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"ধ্বনি"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"কীভাবে উচ্চারণ করবে"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"অনুশীলন শব্দ"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"/v/"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"উপরের দাঁত নিচের ঠোঁটে ছোঁয়াও, তারপর শব্দ বের করো (কম্পন থাকবে)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"very · video · village · travel · give · love · seven"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"/w/"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ঠোঁট গোল করো, দাঁত ছোঁয়াবে না"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"water · we · will · would · away · one"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"অনুশীলন জোড়া: vine/wine · vest/west · vet/wet · veil/whale — আয়নার সামনে বলো, দাঁত-ঠোঁটের সংস্পর্শ দেখো।"}]},{"type":"heading","attrs":{"level":4},"content":[{"type":"text","text":"সমস্যা ২ — /z/ বনাম /j/"}]},{"type":"paragraph","content":[{"type":"text","text":"বাংলায় /z/ ধ্বনি দুর্বল, তাই \"zoo\" → \"joo\", \"zero\" → \"jero\" হয়। এটি বোধগম্যতায় সরাসরি আঘাত করে।"}]},{"type":"paragraph","content":[{"type":"text","text":"অনুশীলন: zoo · zero · lazy · busy · cousin · music · easy · always · because · use"}]},{"type":"paragraph","content":[{"type":"text","text":"কৌশল: /s/ বলো, তারপর গলায় কম্পন যোগ করো — সেটাই /z/। \"bus\" → \"buzz\"।"}]},{"type":"heading","attrs":{"level":4},"content":[{"type":"text","text":"সমস্যা ৩ — /s/ বনাম /ʃ/ (sh)"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"এই ভুলটি সবচেয়ে বিব্রতকর বাংলায় \"স\" প্রায়ই \"শ\" হিসেবে উচ্চারিত হয়। ফলে \"seat\" → \"sheet\", \"sea\" → \"she\", \"sort\" → \"short\" হয়ে যায়। এটি শুধু নম্বরের প্রশ্ন নয় — এটি বোধগম্যতার প্রশ্ন, কারণ সম্পূর্ণ ভিন্ন শব্দ শোনা যায়। এটিকে সর্বোচ্চ অগ্রাধিকার দাও।"}]}]},{"type":"paragraph","content":[{"type":"text","text":"অনুশীলন জোড়া: seat/sheet · see/she · sea/she · save/shave · sort/short · sock/shock · sign/shine · sell/shell"}]},{"type":"paragraph","content":[{"type":"text","text":"কৌশল: /s/ বলার সময় জিভের ডগা দাঁতের কাছে, ঠোঁট সমতল (হাসির মতো)। /ʃ/ বলার সময় জিভ পিছনে, ঠোঁট গোল।"}]},{"type":"heading","attrs":{"level":4},"content":[{"type":"text","text":"সমস্যা ৪ — /θ/ ও /ð/ (th)"}]},{"type":"paragraph","content":[{"type":"text","text":"বাংলায় \"th\" নেই, তাই \"think\" → \"tink\", \"this\" → \"dis\" হয়। এটি Band 6-7 প্রার্থীদের মধ্যেও থেকে যায়।"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"ধ্বনি"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"উদাহরণ শব্দ"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"কীভাবে"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"/θ/ (অঘোষ)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"think · three · thank · month · both · health · nothing"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"জিভের ডগা দাঁতের মাঝে হালকা রেখে বাতাস ছাড়ো"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"/ð/ (ঘোষ)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"this · that · they · the · mother · brother · with"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"একই অবস্থান, কিন্তু গলায় কম্পন"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"গুরুত্বপূর্ণ পরিপ্রেক্ষিত: এই ভুলটি সাধারণত বোধগম্যতা নষ্ট করে না (\"tink\" শুনলেও মানুষ \"think\" বোঝে)। তাই /s/-/ʃ/ ও /v/-/w/ আগে ঠিক করো, \"th\" পরে।"}]},{"type":"heading","attrs":{"level":4},"content":[{"type":"text","text":"সমস্যা ৫ — শব্দের শুরুতে অতিরিক্ত স্বরধ্বনি"}]},{"type":"paragraph","content":[{"type":"text","text":"\"school\" → \"iskool\", \"station\" → \"istation\", \"special\" → \"ispecial\"। বাংলায় শব্দের শুরুতে দুটি ব্যঞ্জন পাশাপাশি বসে না, তাই মাঝখানে একটি স্বর ঢুকে যায়।"}]},{"type":"paragraph","content":[{"type":"text","text":"অনুশীলন: school · student · street · state · speak · sport · sky — থেমে না গিয়ে s-এর পরপরই পরের ব্যঞ্জন বলো: s-kool, s-tudent, s-treet।"}]},{"type":"heading","attrs":{"level":4},"content":[{"type":"text","text":"সমস্যা ৬ — শেষের ব্যঞ্জন গিলে ফেলা"}]},{"type":"paragraph","content":[{"type":"text","text":"\"asked\" → \"ask\", \"helped\" → \"help\", \"worked\" → \"work\"। এতে past tense হারিয়ে যায়, যা সরাসরি Grammar-এ শোনা যায় — অর্থাৎ একটি pronunciation সমস্যা GRA-তেও নম্বর কমায়।"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"-ed উচ্চারণ"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"নিয়ম"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"উদাহরণ"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"/t/"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অঘোষ ধ্বনির পরে (p, k, s, f, sh, ch)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"helped · worked · watched · finished"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"/d/"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ঘোষ ধ্বনি ও স্বরের পরে"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"played · lived · called · enjoyed"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"/ɪd/"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"/t/ বা /d/-এর পরে"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"wanted · needed · decided · started"}]}]}]}]},{"type":"heading","attrs":{"level":4},"content":[{"type":"text","text":"সমস্যা ৭ — Word Stress ভুল জায়গায়"}]},{"type":"paragraph","content":[{"type":"text","text":"ইংরেজিতে জোর ভুল জায়গায় পড়লে শব্দটি চেনা যায় না। এটি বাংলাদেশি শিক্ষার্থীদের সবচেয়ে অবহেলিত সমস্যা।"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","cont