  values (v_foundations, 'Exam Day Strategy', 'exam-day-strategy', 'The 72 hours before your test, what to do once you''re in the room, and five things that really cost marks.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অধ্যায় ১৯ — পরীক্ষার দিনের কৌশল"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"১৯.১ আগের ৭২ ঘণ্টা"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"সময়"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"যা করবে"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"যা করবে না"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৩ দিন আগে"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"দুটি সম্পূর্ণ mock (১৪ মিনিট), রেকর্ড করে শোনা"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"নতুন কৌশল শেখা শুরু করা"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"২ দিন আগে"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"নিজের error list ও idiomatic phrase তালিকা জোরে পড়া"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"নতুন ৫০টি শব্দ মুখস্থ করা"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"১ দিন আগে"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"হালকা অনুশীলন (২০ মিনিট), ভালো ঘুম"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"সারারাত জেগে model answer পড়া"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"পরীক্ষার সকাল"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"১০ মিনিট জোরে ইংরেজি বলা — কণ্ঠ ও মুখ \"গরম\" করা"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"নীরব থাকা; ঠান্ডা মুখে পরীক্ষায় ঢোকা"}]}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"সবচেয়ে কম ব্যবহৃত অথচ কার্যকর টিপ পরীক্ষার সকালে অন্তত ১০ মিনিট জোরে ইংরেজি বলো — নিজের সাথে, আয়নার সামনে, যেকোনো বিষয়ে। গায়কেরা যেমন গানের আগে কণ্ঠ গরম করেন, ঠিক তেমন। যারা সরাসরি নীরবতা থেকে পরীক্ষায় ঢোকে, তাদের প্রথম ২ মিনিট (মানে পুরো Part 1-এর প্রথম টপিক) নষ্ট হয়ে যায় আটকে আটকে।"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"১৯.২ ঘরে ঢোকার পর"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"হাসো এবং চোখে চোখ রাখো। এতে নম্বর নেই, কিন্তু তোমার নিজের স্নায়ু শান্ত হয় — আর শান্ত স্নায়ু মানে ভালো fluency।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"স্বাভাবিক গতিতে কথা বলো। নার্ভাস হলে মানুষ দ্রুত বলে ফেলে, তখন উচ্চারণ ভেঙে যায়। ধীর কিন্তু প্রবাহমান — এটাই আদর্শ।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"প্রশ্ন না বুঝলে জিজ্ঞেস করো। Sorry, could you repeat that? — এতে কোনো নম্বর কাটা যায় না। বরং ভুল প্রশ্নের উত্তর দিলে coherence-এ ক্ষতি হয়।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Part 2-তে নোট নাও। কাগজ-পেন্সিল দেওয়া হয়। ১ মিনিট চুপচাপ বসে থাকা মানে ৬০ সেকেন্ড নষ্ট।"}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"তিনটি জিনিস যা examiner-কে বিরক্ত করে না — কিন্তু শিক্ষার্থীরা ভয় পায় থেমে ভাবা — স্বাভাবিক ও গ্রহণযোগ্য, যদি ইংরেজিতে থামো (Let me think for a moment)। নিজের ভুল শুধরে নেওয়া — একবার-দুবার করলে সেটা দক্ষতার লক্ষণ। বারবার করলে fluency ভাঙে। \"I don''t know\" বলা — বললেও কিছু হবে না, যদি তারপর কিছু যোগ করো: I don''t really know much about this, but I''d guess that..."}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"১৯.৩ পাঁচটি জিনিস যা সত্যিই নম্বর কমায়"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"❌ যা করবে না"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"কেন"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"মুখস্থ উত্তর বলা"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Examiner চিনে ফেলেন; সেই অংশ মূল্যায়নের বাইরে রাখা হয় — কার্যত ফাঁকা সময়"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"এক শব্দে উত্তর দেওয়া"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"মূল্যায়ন করার মতো ভাষা তৈরি হয় না → সব criteria নামে"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"খুব দ্রুত বলা"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"উচ্চারণ ও বাক্যগঠন দুটোই ভেঙে যায়"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"প্রশ্নের বাইরে চলে যাওয়া"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Coherence-এ সরাসরি জরিমানা"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"বাংলা শব্দ ব্যবহার করা"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"বোধগম্যতা নষ্ট; বরং ঘুরিয়ে বলো (অধ্যায় ৭)"}]}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"১৯.৪ যদি নার্ভাস হয়ে সব ভুলে যাও"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"একটা লম্বা শ্বাস নাও। দুই সেকেন্ডের নীরবতা কোনো ক্ষতি করে না।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"সময় কেনার একটি বাক্য বলো: That''s a good question — I haven''t thought about it before."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"সবচেয়ে সহজ সত্য দিয়ে শুরু করো, তারপর কারণ যোগ করো। জটিল উত্তর দেওয়ার চেষ্টা কোরো না।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"মনে রাখো: এটা কথোপকথন, পরীক্ষা নয়। যত বেশি সাধারণ আলাপের মতো ভাববে, তত ভালো বলবে।"}]}]}]}]}'::jsonb, 'published', 'advanced', 8, now());

