  values (v_foundations, 'Practicing Alone: Five Methods', 'practicing-alone-five-methods', 'Record & Review, Shadowing, the 3-minute Daily Drill, Think-Aloud, and finding a speaking partner.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অধ্যায় ২০ — সঙ্গী ছাড়া একা অনুশীলনের পদ্ধতি"}]},{"type":"paragraph","content":[{"type":"text","text":"বাংলাদেশে সবচেয়ে বড় অভিযোগ: \"কার সাথে ইংরেজি বলব?\" — বাস্তবতা হলো, speaking-এর ৮০% উন্নতি একা করা যায়। নিচের পাঁচটি পদ্ধতি প্রমাণিত।"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"২০.১ পদ্ধতি ১ — Record & Review (সবচেয়ে গুরুত্বপূর্ণ)"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"একটি প্রশ্ন নাও (Appendix থেকে)। ফোনের রেকর্ডার চালু করো।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"উত্তর দাও — থেমো না, শুধরাতে যেও না।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"নিজের রেকর্ডিং শোনো এবং তিনটি জিনিস খোঁজো: (ক) কোথায় থেমেছি, (খ) কোন শব্দ বারবার বলেছি, (গ) কোন বাক্যে grammar ভুল করেছি।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"একই প্রশ্নের উত্তর আবার দাও, ওই তিনটি ঠিক করে।"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"সপ্তাহে একবার প্রথম দিনের রেকর্ডিংয়ের সাথে আজকেরটা তুলনা করো। এই তুলনাটাই সবচেয়ে বড় অনুপ্রেরণা — উন্নতি নিজের কানে শুনতে পাবে।"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"২০.২ পদ্ধতি ২ — Shadowing (উচ্চারণ ও ছন্দের জন্য)"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"BBC, TED বা যেকোনো native speaker-এর ১–২ মিনিটের ভিডিও নাও (subtitle সহ)।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"একবার শোনো।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"আবার চালাও এবং তাঁর সাথে সাথে, প্রায় একই গতিতে বলো — শব্দ নয়, সুর ও ছন্দ নকল করার চেষ্টা করো।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"প্রতিদিন ১০ মিনিট, একই ক্লিপ এক সপ্তাহ।"}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"কেন shadowing এত কাজ করে বাংলা syllable-timed ভাষা — প্রতিটি অক্ষরে প্রায় সমান সময় ও জোর। ইংরেজি stress-timed — কিছু শব্দে জোর, বাকিগুলো দ্রুত ও দুর্বল। বই পড়ে এই ছন্দ শেখা যায় না; নকল করে শেখা যায়। Shadowing হলো সরাসরি সেই ছন্দ শরীরে ঢোকানোর পদ্ধতি।"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"২০.৩ পদ্ধতি ৩ — ৩ মিনিটের Daily Drill"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"সময়"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"কাজ"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"১ মিনিট"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"একটি Part 1 প্রশ্নের উত্তর (৩–৪ বাক্য)"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"১ মিনিট"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"একটি cue card-এর জন্য নোট তৈরি"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"১ মিনিট"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"সেই cue card-এ যতটা পারো বলা"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"মাত্র ৩ মিনিট, কিন্তু প্রতিদিন করলে ৩০ দিনে ৯০ মিনিটের বাস্তব speaking অনুশীলন হয়ে যায় — এবং সবচেয়ে গুরুত্বপূর্ণ, অভ্যাসটা তৈরি হয়।"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"২০.৪ পদ্ধতি ৪ — Think-Aloud (দিনে যেকোনো সময়)"}]},{"type":"paragraph","content":[{"type":"text","text":"দৈনন্দিন কাজ করতে করতে মনে মনে নয়, ফিসফিস করে ইংরেজিতে বর্ণনা করো: I''m making tea now. The water''s boiling. I should probably buy more sugar tomorrow..."}]},{"type":"paragraph","content":[{"type":"text","text":"এটি হাস্যকর শোনালেও অত্যন্ত কার্যকর — কারণ এতে বাংলায় ভেবে অনুবাদ করার অভ্যাস ভাঙে, যা Fluency-র এক নম্বর শত্রু।"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"২০.৫ পদ্ধতি ৫ — Speaking Partner খুঁজে নেওয়া"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"একজন বন্ধু বা সহপাঠী — সপ্তাহে ২ দিন, ২০ মিনিট, শুধু ইংরেজিতে।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"একজনের কাছে প্রশ্ন, অন্যজন উত্তর দেবে; তারপর ভূমিকা বদল।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"শোনার সময় নোট নাও — সঙ্গীর ৩টি ভুল লিখে রাখো, শেষে জানাও। শোনার এই কাজটাও তোমাকে শেখায়।"}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"একটি সতর্কতা দুই বাংলাভাষী একসাথে অনুশীলন করলে একে অন্যের উচ্চারণ ভুল ধরতে পারবে না — কারণ দুজনের ভুল একই। তাই partner practice-এর পাশাপাশি shadowing অবশ্যই চালিয়ে যাও, যেখানে মডেল একজন native speaker।"}]}]}]}'::jsonb, 'published', 'advanced', 10, now());

  -- Self-Assessment & Error Log
  insert into lessons (node_id, title, slug, excerpt, content, status, difficulty, estimated_minutes, published_at)
  values (v_foundations, 'Self-Assessment & Error Log', 'self-assessment-and-error-log', 'A checklist for each criterion, and a personal error log to track your own patterns.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অধ্যায় ২১ — নিজের মূল্যায়ন ও Error Log"}]},{"type":"paragraph","content":[{"type":"text","text":"শিক্ষক ছাড়া উন্নতির একমাত্র উপায় হলো কাঠামোবদ্ধ আত্মমূল্যায়ন। \"মনে হচ্ছে ভালোই বলছি\" দিয়ে কিছু হয় না।"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"২১.১ Self-Assessment Checklist"}]},{"type":"paragraph","content":[{"type":"text","text":"প্রতিটি রেকর্ডিং শোনার পর এই ২০টি প্রশ্নের উত্তর দাও। ১৬টির বেশি \"হ্যাঁ\" মানে তুমি Band 7-এর কাছাকাছি।"}]},{"type":"heading","attrs":{"level":4},"content":[{"type":"text","text":"Fluency & Coherence"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"☐ কোনো উত্তরই এক বাক্যে শেষ হয়নি?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"☐ ৩ সেকেন্ডের বেশি নীরব থামা ছিল না?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"☐ যখন থেমেছি, ইংরেজিতে থেমেছি (well, I suppose) — \"উম\" বা \"মানে\" নয়?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"☐ একই শব্দ বা বাক্য বারবার বলিনি?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"☐ প্রতিটি উত্তরে একটি কারণ (because, since, the reason is) ছিল?"}]}]}]},{"type":"heading","attrs":{"level":4},"content":[{"type":"text","text":"Lexical Resource"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"☐ প্রশ্নের শব্দ হুবহু পুনরাবৃত্তি না করে ঘুরিয়ে বলেছি?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"☐ অন্তত ৩টি idiomatic কথ্য শব্দবন্ধ ব্যবহার করেছি?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"☐ একই বিশেষণ (good, nice, very) বারবার ব্যবহার করিনি?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"☐ বিষয়ভিত্তিক শব্দ ব্যবহার করেছি (রান্না → ingredients, recipe)?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"☐ কোনো বাংলা শব্দ ব্যবহার করিনি?"}]}]}]},{"type":"heading","attrs":{"level":4},"content":[{"type":"text","text":"Grammar"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"☐ Subject–verb agreement ঠিক ছিল?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"☐ Tense ধারাবাহিক ছিল (অতীতের গল্পে past)?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"☐ অন্তত একটি conditional ব্যবহার করেছি?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"☐ অন্তত একটি relative clause ব্যবহার করেছি?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"☐ Article (a/an/the) ঠিক জায়গায় ছিল?"}]}]}]},{"type":"heading","attrs":{"level":4},"content":[{"type":"text","text":"Pronunciation"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"☐ নিজের রেকর্ডিং শুনে প্রতিটি শব্দ বুঝতে পেরেছি?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"☐ শব্দের জোর (word stress) ঠিক জায়গায় ছিল?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"☐ বাক্যের সুর ওঠানামা করেছে, একঘেয়ে সমতল ছিল না?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"☐ শব্দের শেষের ব্যঞ্জন (asked, worked) স্পষ্ট ছিল?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"☐ গতি স্বাভাবিক ছিল — খুব দ্রুত নয়?"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"২১.২ তোমার ব্যক্তিগত Error Log"}]},{"type":"paragraph","content":[{"type":"text","text":"একটি খাতায় এই টেবিল বানাও এবং প্রতিটি রেকর্ডিংয়ের পর পূরণ করো। একই ভুল তিনবার এলে সেটাই তোমার প্রধান দুর্বলতা।"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"তারিখ"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"যা বলেছিলাম"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"যা বলা উচিত ছিল"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"ধরন"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"কতবার"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"১০ মার্চ"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"I am doing job in a bank."}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"I work at a bank. / I have a job at a bank."}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Banglish"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৪"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"১০ মার্চ"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"I am living here since five years."}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"I have been living here for five years."}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Tense"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৩"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"১২ মার্চ"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"\"bhery\" (very)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"/v/ — উপরের দাঁত নিচের ঠোঁটে"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"উচ্চারণ"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৬"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":""}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":""}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":""}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":""}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":""}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":""}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":""}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":""}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":""}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":""}]}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"সফলতার তিনটি সংকেত সংকেত ১: কথা বলার সময় বাংলা বাক্য মাথায় আসছে না — সরাসরি ইংরেজিতে ভাবছ। সংকেত ২: কোনো প্রশ্নে আটকে গেলে আতঙ্কিত না হয়ে স্বাভাবিকভাবে ঘুরিয়ে বলতে পারছ। সংকেত ৩: নিজের রেকর্ডিং শুনে আর অস্বস্তি লাগছে না — এটাই সবচেয়ে বড় লক্ষণ যে আত্মবিশ্বাস এসে গেছে।"}]}]},{"type":"paragraph","content":[{"type":"text","text":"APPENDIX"}]},{"type":"paragraph","content":[{"type":"text","text":"রিসোর্স"}]},{"type":"paragraph","content":[{"type":"text","text":"প্রশ্নব্যাংক • ভাষার ভাণ্ডার • ৩০ দিনের প্ল্যান"}]}]}'::jsonb, 'published', 'advanced', 8, now());

