  insert into lessons (node_id, title, slug, excerpt, content, status, difficulty, estimated_minutes, published_at)
  values (v_foundations, 'Functional Language Bank', 'functional-language-bank', 'A quick-reference bank of functional phrases for the test.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Appendix D — Functional Language Bank"}]},{"type":"paragraph","content":[{"type":"text","text":"প্রতিটি কাজের জন্য দুই-তিনটি বেছে নিয়ে নিজের করে ফেলো — সব ব্যবহারের চেষ্টা কোরো না।"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"কাজ"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"শব্দবন্ধ"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"সময় কেনা"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"That''s an interesting question. • Let me think for a second. • I''ve never really thought about that before."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"মতামত দেওয়া"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"I''d say... • Personally, I think... • The way I see it... • If you ask me..."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"নরম মতামত (hedging)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"It probably depends on... • I suppose... • To some extent... • More often than not..."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"একমত"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Absolutely. • That''s exactly how I feel. • I couldn''t agree more."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"দ্বিমত (ভদ্রভাবে)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"I see what you mean, but... • I''m not so sure about that. • That''s one way of looking at it, though..."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"উদাহরণ"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Take my brother, for example... • A good case would be... • Just to give you an idea..."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"বৈসাদৃশ্য"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Whereas... • On the flip side... • Having said that... • Then again..."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অনুমান করা"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"I''d imagine that... • It could well be that... • My guess is that... • There''s a good chance that..."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"তুলনা করা"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"compared with... • nowhere near as... as... • far more ... than... • much the same as..."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ঘুরিয়ে বলা (শব্দ ভুলে গেলে)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"It''s a kind of... • It''s the thing you use for... • I can''t think of the word, but it''s like a..."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"প্রশ্ন বুঝতে না পারলে"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Sorry, could you repeat that? • Do you mean ... ? • Sorry, I didn''t catch that."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"নিজেকে শুধরানো"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Sorry, what I meant was... • Or rather... • Actually, let me rephrase that."}]}]}]}]}]}'::jsonb, 'published', 'advanced', 8, now());

