  insert into lessons (node_id, title, slug, excerpt, content, status, difficulty, estimated_minutes, published_at)
  values (v_foundations, 'Your 30-Day Speaking Plan', 'your-30-day-speaking-plan', 'A day-by-day plan to take you from foundations to exam-ready.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Appendix E — ৩০ দিনের Speaking Plan"}]},{"type":"paragraph","content":[{"type":"text","text":"দিনে ৩০–৪৫ মিনিট। প্রতিদিন রেকর্ডিং বাধ্যতামূলক — এটাই একমাত্র শর্ত যা ভাঙলে প্ল্যান কাজ করবে না।"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"দিন"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"পড়া"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"অনুশীলন (রেকর্ড করো)"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"১–২"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ১–৩"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"১০টি Part 1 প্রশ্ন; প্রথম রেকর্ডিংটি সংরক্ষণ করে রাখো (তুলনার জন্য)"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৩–৫"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ৪–৫"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"দিনে ১৫টি Part 1 প্রশ্ন — প্রতিটিতে কারণ যোগ করার অনুশীলন"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৬–৭"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ৬–৭"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"১৫টি প্রশ্ন; থামার সময় ইংরেজিতে থামার অনুশীলন"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৮–১০"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ৮–৯"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"দিনে ১০টি প্রশ্ন + প্রতিদিন ৩টি নতুন idiomatic phrase ব্যবহার"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"১১–১২"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ১০–১১"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৫টি Cue Card — শুধু নোট নেওয়ার অনুশীলন (বলা নয়)"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"১৩–১৪"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ১২"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"নিজের error log শুরু করো; ৩টি পুরনো রেকর্ডিং শুনে ভুল লেখো"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"১৫–১৭"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ১৩–১৪"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"প্রতিদিন ১০ মিনিট shadowing + ৫টি Part 1 প্রশ্ন"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"১৮–১৯"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ১৫"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"নিজের সমস্যাযুক্ত ধ্বনিগুলোর drill + ৪টি Cue Card (পূর্ণ ২ মিনিট)"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"২০–২১"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ১৬"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"১৫টি Part 1 প্রশ্ন — model-এর সাথে নিজের উত্তর তুলনা"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"২২–২৪"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ১৭"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"প্রতিদিন ৩টি Cue Card, ঘড়ি ধরে"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"২৫–২৬"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ১৮"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"প্রতিদিন ১০টি Part 3 প্রশ্ন — ৪–৬ বাক্যের উত্তর"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"২৭"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ১৯"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Full mock ১: Part 1 + 2 + 3, ১৪ মিনিট, একটানা রেকর্ড"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"২৮"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ২০–২১"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Mock ১ শুনে checklist দিয়ে নিজেকে নম্বর দাও"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"২৯"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"error log রিভিশন"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Full mock ২ — শুধু শীর্ষ ৫টি ভুল এড়ানোয় মনোযোগ"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৩০"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"হালকা রিভিশন"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"দিন ১-এর রেকর্ডিং বনাম আজকেরটা শোনো। বিশ্রাম নাও।"}]}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"এই প্ল্যানের তিনটি ব্যর্থতার ঝুঁকি — এবং প্রতিকার ঝুঁকি ১: পড়া হয়, বলা হয় না। প্রতিকার — পড়া বাদ দেওয়া চলবে, রেকর্ডিং নয়। দিনে ৩ মিনিটও যদি হয়, রেকর্ড করো। ঝুঁকি ২: রেকর্ডিং শোনা হয় না। নিজের কণ্ঠ শুনতে প্রথম কয়েকদিন অস্বস্তি লাগে — এটা সবার হয়। তিন দিন পর কেটে যায়। না শুনলে উন্নতি হবে না। ঝুঁকি ৩: Shadowing বাদ দেওয়া। দিন ১৫–১৯ সবচেয়ে গুরুত্বপূর্ণ। উচ্চারণ ও ছন্দ শুধু নকল করেই শেখা যায়, পড়ে নয়।"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"শেষ কথা"}]},{"type":"paragraph","content":[{"type":"text","text":"IELTS Speaking-এ ভালো করার জন্য তোমাকে ইংরেজিতে পণ্ডিত হতে হবে না। স্বাভাবিকভাবে কথা বলতে পারলেই যথেষ্ট।"}]},{"type":"paragraph","content":[{"type":"text","text":"যারা এখানে ৭ বা তার বেশি পায়, তারা আলাদা কিছু করে না। তারা শুধু চারটি কাজ করে:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"কখনো এক বাক্যে উত্তর শেষ করে না — সবসময় একটি কারণ বা উদাহরণ যোগ করে।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"বাংলায় ভেবে অনুবাদ করে না — সরাসরি ইংরেজিতে ভাবে, তাই থামতে হয় না।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"আটকে গেলে আতঙ্কিত হয় না — ঘুরিয়ে বলে, এবং কথা চালিয়ে যায়।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"নিজের কণ্ঠ নিজে শোনে — তাই নিজের ভুলগুলো জানে এবং একে একে বন্ধ করে।"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"এই চারটি অভ্যাস তৈরি করতে ৩০ দিন যথেষ্ট। আজই শুরু করো — Appendix A থেকে প্রথম ১০টি প্রশ্ন নাও, ফোনের রেকর্ডার চালু করো, আর কথা বলা শুরু করো। পড়ে ফেলা একটা অধ্যায়ের চেয়ে রেকর্ড করা একটা উত্তর অনেক বেশি কাজে দেয়।"}]},{"type":"paragraph","content":[{"type":"text","text":"তোমার প্রস্তুতির জন্য শুভকামনা। তোমার accent নিয়ে কোনো সমস্যা নেই — শুধু মুখ খোলার অভ্যাসটা তৈরি করো।"}]}]}'::jsonb, 'published', 'advanced', 8, now());

  -- Part 1 Masterclass: Rules & Technique
  insert into lessons (node_id, title, slug, excerpt, content, status, difficulty, estimated_minutes, published_at)
  values (v_part_1, 'Part 1 Masterclass: Rules & Technique', 'part-1-masterclass', 'Six rules for Part 1, and how to handle the very first question.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অধ্যায় ১৬ — Part 1 Masterclass"}]},{"type":"paragraph","content":[{"type":"text","text":"Part 1-এ examiner তোমাকে স্বস্তিতে আনতে চান এবং একই সাথে তোমার স্বাভাবিক ইংরেজি শুনতে চান। এখানে বিষয়গুলো পরিচিত: বাড়ি, কাজ, পড়াশোনা, খাবার, আবহাওয়া, শখ, ভ্রমণ।"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"১৬.১ Part 1-এর ছয়টি নিয়ম"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"২–৪ বাক্য। এক বাক্য খুব কম, আট বাক্য খুব বেশি।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"সরাসরি উত্তর দিয়ে শুরু করো, তারপর ব্যাখ্যা। \"Do you like X?\" → \"I do, yes —\" তারপর কারণ।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"\"Yes/No\" বলে থেমো না। এটি Part 1-এ নম্বর হারানোর এক নম্বর কারণ।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"নির্দিষ্ট হও। \"I like music\" নয় — \"I''m really into old Bangla band music, especially LRB.\""}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"পুরোপুরি সৎ হওয়ার দরকার নেই। যেটা নিয়ে বেশি কথা বলতে পারবে, সেটাই বলো।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"উৎসাহ দেখাও। একঘেয়ে কণ্ঠে সঠিক উত্তরও ৬-এর বেশি পায় না।"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"১৬.২ প্রথম প্রশ্ন — পরিচয়"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"এই ভুলটি প্রথম ১০ সেকেন্ডেই ছাপ ফেলে ❌ \"Myself Misbah.\" — এটি ইংরেজিতে ভুল এবং examiner সাথে সাথেই বুঝে যান কোন ধরনের প্রস্তুতি নিয়ে এসেছ। ✅ \"My name''s Misbah Uddin, but most people just call me Misbah.\" — স্বাভাবিক, নিখুঁত, এবং সাথে সাথে একটি ভালো প্রথম ছাপ।"}]}]}]}'::jsonb, 'published', 'advanced', 10, now());

  -- Part 1 Model Answers: Hometown
  insert into lessons (node_id, title, slug, excerpt, content, status, difficulty, estimated_minutes, published_at)
  values (v_part_1, 'Part 1 Model Answers: Hometown', 'model-answers-hometown', 'Three Band 8 model answers about your hometown, with a breakdown of why each one works.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":4},"content":[{"type":"text","text":"টপিক: Hometown"}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Where are you from?"}]},{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"I''m from Rajshahi, in the north-west of Bangladesh — it''s a fairly mid-sized city, quite a bit calmer than Dhaka. I was born and raised there, and although I moved away for work a few years ago, I still think of it as home.","label":"🔊 Listen to this answer"}}]},{"type":"paragraph","content":[{"type":"text","text":"I''m from Rajshahi, in the north-west of Bangladesh — it''s a fairly mid-sized city, quite a bit calmer than Dhaka. I was born and raised there, and although I moved away for work a few years ago, I still think of it as home."}]},{"type":"paragraph","content":[{"type":"text","text":"কেন এটা কাজ করে: নির্দিষ্ট (ভৌগোলিক অবস্থান), তুলনা (calmer than Dhaka), idiomatic (born and raised), এবং একটি contrast (although I moved away) — তিনটি criterion একসাথে দেখানো হলো।"}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Is it a good place to live?"}]},{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"For the most part, yes. The pace of life is a lot gentler and the cost of living is nowhere near what it is in the capital. The only real drawback is that job opportunities are limited, which is why so many young people end up leaving — myself included, unfortunately.","label":"🔊 Listen to this answer"}}]},{"type":"paragraph","content":[{"type":"text","text":"For the most part, yes. The pace of life is a lot gentler and the cost of living is nowhere near what it is in the capital. The only real drawback is that job opportunities are limited, which is why so many young people end up leaving — myself included, unfortunately."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Has your hometown changed much in recent years?"}]},{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"Quite a lot, actually. When I was a child there was farmland right at the edge of our neighbourhood, and now it''s all apartment blocks. I''d say it''s a mixed bag — there are far more facilities than there used to be, but it''s lost some of that close-knit feeling it had.","label":"🔊 Listen to this answer"}}]},{"type":"paragraph","content":[{"type":"text","text":"Quite a lot, actually. When I was a child there was farmland right at the edge of our neighbourhood, and now it''s all apartment blocks. I''d say it''s a mixed bag — there are far more facilities than there used to be, but it''s lost some of that close-knit feeling it had."}]},{"type":"paragraph","content":[{"type":"text","text":"কেন এটা কাজ করে: used to, present perfect, comparative, idiom (a mixed bag, close-knit) — বৈচিত্র্যময় grammar স্বাভাবিকভাবে এসেছে।"}]}]}'::jsonb, 'published', 'advanced', 8, now());

  -- Part 1 Model Answers: Work / Study
  insert into lessons (node_id, title, slug, excerpt, content, status, difficulty, estimated_minutes, published_at)
  values (v_part_1, 'Part 1 Model Answers: Work / Study', 'model-answers-work-study', 'Three Band 8 model answers about work or study.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":4},"content":[{"type":"text","text":"টপিক: Work / Study"}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Do you work or are you a student?"}]},{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"I work — I''m an accountant at a mid-sized trading company in Dhaka. I''ve been there for about three years now, mostly handling monthly reporting and audits.","label":"🔊 Listen to this answer"}}]},{"type":"paragraph","content":[{"type":"text","text":"I work — I''m an accountant at a mid-sized trading company in Dhaka. I''ve been there for about three years now, mostly handling monthly reporting and audits."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Do you enjoy your job?"}]},{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"Most of the time, yes. I like the fact that there''s a clear right answer at the end of the day, which suits the way my brain works. What I could do without is the crunch at the end of every quarter — I''m absolutely swamped for about two weeks and barely see my family.","label":"🔊 Listen to this answer"}}]},{"type":"paragraph","content":[{"type":"text","text":"Most of the time, yes. I like the fact that there''s a clear right answer at the end of the day, which suits the way my brain works. What I could do without is the crunch at the end of every quarter — I''m absolutely swamped for about two weeks and barely see my family."}]},{"type":"paragraph","content":[{"type":"text","text":"কেন এটা কাজ করে: Cleft sentence (What I could do without is...) — Band 8-এর সরাসরি চিহ্ন। সাথে idiom (swamped) ও ভারসাম্যপূর্ণ মতামত।"}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What would you change about your job if you could?"}]},{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"If I had the choice, I''d push for more flexible hours. Honestly, most of what I do could be done from anywhere with a laptop, so sitting in traffic for two hours a day feels a bit pointless. Other than that, I''m fairly content.","label":"🔊 Listen to this answer"}}]},{"type":"paragraph","content":[{"type":"text","text":"If I had the choice, I''d push for more flexible hours. Honestly, most of what I do could be done from anywhere with a laptop, so sitting in traffic for two hours a day feels a bit pointless. Other than that, I''m fairly content."}]},{"type":"paragraph","content":[{"type":"text","text":"কেন এটা কাজ করে: Second conditional (If I had... I''d push) — স্বাভাবিকভাবে, জোর করে নয়।"}]}]}'::jsonb, 'published', 'advanced', 8, now());

  -- Part 1 Model Answers: Free Time & Hobbies
  insert into lessons (node_id, title, slug, excerpt, content, status, difficulty, estimated_minutes, published_at)
  values (v_part_1, 'Part 1 Model Answers: Free Time & Hobbies', 'model-answers-free-time-hobbies', 'Band 8 model answers about how you spend your free time.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":4},"content":[{"type":"text","text":"টপিক: Free time & Hobbies"}]},{"type":"paragraph","content":[{"type":"text","text":"Q: What do you usually do in your free time?"}]},{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"It depends on how drained I am, really. On a good weekend I''ll go out with my camera and wander around the old part of the city, but if I''ve had a rough week I''m quite happy just to stay in and watch something mindless.","label":"🔊 Listen to this answer"}}]},{"type":"paragraph","content":[{"type":"text","text":"It depends on how drained I am, really. On a good weekend I''ll go out with my camera and wander around the old part of the city, but if I''ve had a rough week I''m quite happy just to stay in and watch something mindless."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Did you have any hobbies as a child?"}]},{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"I was obsessed with cricket, like pretty much every boy in my neighbourhood. We used to play in the street until it got dark and our mothers came out shouting. I wasn''t particularly good, to be fair, but I loved it.","label":"🔊 Listen to this answer"}}]},{"type":"paragraph","content":[{"type":"text","text":"I was obsessed with cricket, like pretty much every boy in my neighbourhood. We used to play in the street until it got dark and our mothers came out shouting. I wasn''t particularly good, to be fair, but I loved it."}]},{"type":"paragraph","content":[{"type":"text","text":"কেন এটা কাজ করে: used to, past continuous, self-deprecating হাস্যরস — ব্যক্তিত্ব দেখানো Band 8-এ বড় ভূমিকা রাখে।"}]}]}'::jsonb, 'published', 'advanced', 6, now());

  -- Part 1 Model Answers: Food
  insert into lessons (node_id, title, slug, excerpt, content, status, difficulty, estimated_minutes, published_at)
  values (v_part_1, 'Part 1 Model Answers: Food', 'model-answers-food', 'Band 8 model answers about food.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":4},"content":[{"type":"text","text":"টপিক: Food"}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Do you prefer eating at home or eating out?"}]},{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"At home, without a doubt. Partly it''s the cost, but mainly it''s that home-cooked food just sits better with me — restaurant food here tends to be quite heavy on oil. That said, I do enjoy going out once in a while, mostly for the company rather than the food itself.","label":"🔊 Listen to this answer"}}]},{"type":"paragraph","content":[{"type":"text","text":"At home, without a doubt. Partly it''s the cost, but mainly it''s that home-cooked food just sits better with me — restaurant food here tends to be quite heavy on oil. That said, I do enjoy going out once in a while, mostly for the company rather than the food itself."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Are there any foods you dislike?"}]},{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"A few, yes. I''ve never been able to get on with bitter gourd — my mother swears it''s good for you, but the taste is just unbearable to me. Other than that I''m pretty easy-going about food.","label":"🔊 Listen to this answer"}}]},{"type":"paragraph","content":[{"type":"text","text":"A few, yes. I''ve never been able to get on with bitter gourd — my mother swears it''s good for you, but the taste is just unbearable to me. Other than that I''m pretty easy-going about food."}]}]}'::jsonb, 'published', 'advanced', 6, now());

  -- Part 1 Model Answers: Technology
  insert into lessons (node_id, title, slug, excerpt, content, status, difficulty, estimated_minutes, published_at)
  values (v_part_1, 'Part 1 Model Answers: Technology', 'model-answers-technology', 'Band 8 model answers about technology, plus a caution about Part 1 answer length.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":4},"content":[{"type":"text","text":"টপিক: Technology"}]},{"type":"paragraph","content":[{"type":"text","text":"Q: How much time do you spend on your phone?"}]},{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"Far more than I''d like to admit — probably four or five hours a day, if I''m honest. A fair bit of that is work, but a lot of it is just scrolling out of habit. I''ve tried cutting down a few times, though it never seems to last more than a week.","label":"🔊 Listen to this answer"}}]},{"type":"paragraph","content":[{"type":"text","text":"Far more than I''d like to admit — probably four or five hours a day, if I''m honest. A fair bit of that is work, but a lot of it is just scrolling out of habit. I''ve tried cutting down a few times, though it never seems to last more than a week."}]},{"type":"paragraph","content":[{"type":"text","text":"Q: Has technology made your life easier?"}]},{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"On balance, definitely. Things like mobile banking have genuinely transformed everyday life here — my parents used to queue at the bank for an entire morning to send money, and now it takes thirty seconds. The flip side, of course, is that you''re never really off duty.","label":"🔊 Listen to this answer"}}]},{"type":"paragraph","content":[{"type":"text","text":"On balance, definitely. Things like mobile banking have genuinely transformed everyday life here — my parents used to queue at the bank for an entire morning to send money, and now it takes thirty seconds. The flip side, of course, is that you''re never really off duty."}]},{"type":"paragraph","content":[{"type":"text","text":"কেন এটা কাজ করে: On balance, The flip side, genuinely transformed — Part 3-এর মতো বিশ্লেষণী ভাষা, কিন্তু Part 1-এর দৈর্ঘ্যে।"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"১৬.৪ Part 1-এর জন্য একটি সতর্কতা"}]},{"type":"paragraph","content":[{"type":"text","text":"Examiner প্রায়ই তোমাকে মাঝপথে থামিয়ে পরের প্রশ্নে যাবেন — এটি খারাপ লক্ষণ নয়। Part 1-এ তাঁকে নির্দিষ্ট সংখ্যক প্রশ্ন করতেই হয়, তাই সময় বাঁচাতে থামান। এতে বিচলিত হয়ো না।"}]}]}'::jsonb, 'published', 'advanced', 8, now());

