  insert into lessons (node_id, title, slug, excerpt, content, status, difficulty, estimated_minutes, published_at)
  values (v_part_3, 'Appendix C: 60 Part 3 Discussion Questions', 'appendix-c-60-discussion-questions', '60 real Part 3 discussion questions across 6 categories, for practice.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Appendix C — Part 3: ৬০টি Discussion Question"}]},{"type":"paragraph","content":[{"type":"text","text":"প্রতিটির উত্তর ৪–৬ বাক্যে, একটি মতামত + কারণ + উদাহরণ সহ।"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Education & Work"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Should schools focus more on practical skills than academic subjects?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"How has the way people learn changed in recent decades?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Do you think university education should be free?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Why do some people change careers in their thirties?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Will people still work in offices in twenty years?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Is it better to work for a large company or a small one?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"How important is job satisfaction compared with salary?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Should employers be responsible for training their staff?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Do young people today have more opportunities than their parents did?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"What are the disadvantages of working from home?"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Technology & Media"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Has social media improved communication or damaged it?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Should governments regulate what people post online?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"How has technology changed family life?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Do people rely too much on their phones?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Will artificial intelligence replace many jobs?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Is online news as reliable as newspapers?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Should children be allowed to use smartphones at school?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"How has shopping changed because of the internet?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Do you think privacy is possible in the modern world?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"What are the risks of people getting all their information online?"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Society & Culture"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Why do people move from rural areas to cities?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Are traditional customs disappearing in your country?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Should governments spend money on preserving old buildings?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"How important is it for children to learn about their culture?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Do people today have less free time than in the past?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Is the gap between rich and poor increasing?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"What role should older people play in society?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Are festivals as important as they used to be?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Do you think globalisation threatens local cultures?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"How can communities become closer?"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Environment & Health"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Whose responsibility is it to protect the environment?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Can individuals really make a difference to climate change?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Should there be higher taxes on cars in city centres?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"How can governments encourage people to recycle?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Why are people less active than in the past?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Should healthcare be free for everyone?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"How can schools encourage children to eat healthily?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Is stress an unavoidable part of modern life?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Should governments ban unhealthy food advertising?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"What can be done about air pollution in large cities?"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Personal Development & Abstract"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Is success mainly the result of hard work or luck?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Why do some people find it difficult to make decisions?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Is it important to have goals?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Do people become more patient as they get older?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"How do people usually deal with failure?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Is competition always a good thing?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Do you think money makes people happy?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"What makes a person a good leader?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Should children be given pocket money?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"How important is it to keep learning throughout life?"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Comparison & Prediction"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"How is childhood today different from thirty years ago?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Will libraries still exist in the future?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"How might cities change in the next fifty years?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Do you think people will travel less in the future?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"How has the role of women in the workplace changed?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Will printed books disappear?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"How might family structures change in the coming decades?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Do you think future generations will be happier than today''s?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"How could transport be improved in your country?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"What changes would you like to see in education?"}]}]}]}]}'::jsonb, 'published', 'advanced', 20, now());

